    Ayah(27, 78, "اِنَّهُمْ كَانُوْا لَا يَرْجُوْنَ حِسَابًاۙ", "Innahum kānū lā yarjūna ḥisābā(n).", "Sesungguhnya mereka tidak pernah mengharapkan perhitungan."),
    Ayah(28, 78, "وَّكَذَّبُوْا بِاٰيٰتِنَا كِذَّابًاۗ", "Wa każżabū bi'āyātinā kiżżābā(n).", "Mereka benar-benar mendustakan ayat-ayat Kami."),
    Ayah(29, 78, "وَكُلَّ شَيْءٍ اَحْصَيْنٰهُ كِتٰبًاۙ", "Wa kulla syai'in aḥṣaināhu kitābā(n).", "Segala sesuatu telah Kami catat dalam kitab (catatan amal manusia)."),
    Ayah(30, 78, "فَذُوْقُوْا فَلَنْ نَّزِيْدَكُمْ اِلَّا عَذَابًا ࣖ", "Fa żūqū falan nazīdakum illā ‘ażābā(n)", "Oleh karena itu, rasakanlah! Tidak akan Kami tambahkan kepadamu, kecuali azab."),
    Ayah(31, 78, "اِنَّ لِلْمُتَّقِيْنَ مَفَازًاۙ", "Inna lil-muttaqīna mafāzā(n).", "Sesungguhnya bagi orang-orang yang bertakwa (ada) kemenangan (surga),"),
    Ayah(32, 78, "حَدَاۤىِٕقَ وَاَعْنَابًاۙ", "Ḥadā'iqa wa a‘nābā(n).", "(yaitu) kebun-kebun, buah anggur,"),
    Ayah(33, 78, "وَّكَوَاعِبَ اَتْرَابًاۙ", "Wa kawā‘iba atrābā(n).", "gadis-gadis molek yang sebaya,"),
    Ayah(34, 78, "وَّكَأْسًا دِهَاقًاۗ", "Wa ka'san dihāqā(n).", "dan gelas-gelas yang penuh (berisi minuman)."),
    Ayah(35, 78, "لَا يَسْمَعُوْنَ فِيْهَا لَغْوًا وَّلَا كِذّٰبًا", "Lā yasma‘ūna fīhā lagwaw wa lā kiżżābā(n).", "Di sana mereka tidak mendengar percakapan yang sia-sia dan tidak pula (perkataan) dusta."),
    Ayah(36, 78, "جَزَاۤءً مِّنْ رَّبِّكَ عَطَاۤءً حِسَابًاۙ", "Jazā'am mir rabbika ‘aṭā'an ḥisābā(n).", "(Hal itu) sebagai balasan (dan) pemberian yang banyak dari Tuhanmu,"),
    Ayah(37, 78, "رَّبِّ السَّمٰوٰتِ وَالْاَرْضِ وَمَا بَيْنَهُمَا الرَّحْمٰنِ لَا يَمْلِكُوْنَ مِنْهُ خِطَابًاۚ", "Rabbis-samāwāti wal-arḍi wa mā bainahumar-raḥmāni lā yamlikūna minhu khiṭābā(n).", "(yaitu) Tuhan (pemelihara) langit, bumi, dan apa yang ada di antara keduanya, Yang Maha Pengasih. Mereka tidak memiliki (hak) berbicara dengan-Nya."),
    Ayah(38, 78, "يَوْمَ يَقُوْمُ الرُّوْحُ وَالْمَلٰۤىِٕكَةُ صَفًّاۙ لَّا يَتَكَلَّمُوْنَ اِلَّا مَنْ اَذِنَ لَهُ الرَّحْمٰنُ وَقَالَ صَوَابًا", "Yauma yaqūmur-rūḥu wal-malā'ikatu ṣaffā(n), lā yatakallamūna illā man ażina lahur-raḥmānu wa qāla ṣawābā(n).", "Pada hari ketika Rūḥ743) dan malaikat berdiri bersaf-saf. Mereka tidak berbicara, kecuali yang diizinkan oleh Tuhan Yang Maha Pengasih dan dia mengatakan yang benar."),
    Ayah(39, 78, "ذٰلِكَ الْيَوْمُ الْحَقُّۚ فَمَنْ شَاۤءَ اتَّخَذَ اِلٰى رَبِّهٖ مَاٰبًا", "Żālikal-yaumul-ḥaqq(u), faman syā'attakhaża ilā rabbihī ma'ābā(n).", "Itulah hari yang hak (pasti terjadi). Siapa yang menghendaki (keselamatan) niscaya menempuh jalan kembali kepada Tuhannya (dengan beramal saleh)."),
    Ayah(40, 78, "اِنَّآ اَنْذَرْنٰكُمْ عَذَابًا قَرِيْبًا ەۙ يَّوْمَ يَنْظُرُ الْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُوْلُ الْكٰفِرُ يٰلَيْتَنِيْ كُنْتُ تُرٰبًا ࣖ", "Innā anżarnākum ‘ażāban qarībā(n), yauma yanẓurul-mar'u mā qaddamat yadāhu wa yaqūlul-kāfiru yā laitanī kuntu turābā(n).", "Sesungguhnya Kami telah memperingatkan kamu akan azab yang dekat pada hari (ketika) manusia melihat apa yang telah diperbuat oleh kedua tangannya dan orang kafir berkata, “Oh, seandainya saja aku menjadi tanah.”"),
)

internal fun quranFullAyahs79(): List<Ayah> = listOf(
    Ayah(1, 79, "وَالنّٰزِعٰتِ غَرْقًاۙ", "Wan-nāzi‘āti garqā(n).", "Demi (malaikat) yang mencabut (nyawa orang kafir) dengan keras,"),
    Ayah(2, 79, "وَّالنّٰشِطٰتِ نَشْطًاۙ", "Wan-nāsyiṭāti nasyṭā(n).", "demi (malaikat) yang mencabut (nyawa orang mukmin) dengan lemah lembut,"),
    Ayah(3, 79, "وَّالسّٰبِحٰتِ سَبْحًاۙ", "Was-sābiḥāti sabḥā(n).", "demi (malaikat) yang cepat (menunaikan tugasnya) dengan mudah,"),
    Ayah(4, 79, "فَالسّٰبِقٰتِ سَبْقًاۙ", "Fas-sābiqāti sabqā(n).", "(malaikat) yang bergegas (melaksanakan perintah Allah) dengan cepat,"),
    Ayah(5, 79, "فَالْمُدَبِّرٰتِ اَمْرًاۘ", "Fal-mudabbirāti amrā(n).", "dan (malaikat) yang mengatur urusan (dunia),744)"),
    Ayah(6, 79, "يَوْمَ تَرْجُفُ الرَّاجِفَةُۙ", "Yauma tarjufur-rājifah(tu).", "(kamu benar-benar akan dibangkitkan) pada hari ketika tiupan pertama mengguncang (alam semesta)."),
    Ayah(7, 79, "تَتْبَعُهَا الرَّادِفَةُ ۗ", "Tatba‘uhar-rādifah(tu).", "(Tiupan pertama) itu diiringi oleh tiupan kedua."),
    Ayah(8, 79, "قُلُوْبٌ يَّوْمَىِٕذٍ وَّاجِفَةٌۙ", "Qulūbuy yauma'iżiw wājifah(tun).", "Hati manusia pada hari itu merasa sangat takut;"),
    Ayah(9, 79, "اَبْصَارُهَا خَاشِعَةٌ ۘ", "Abṣāruhā khāsyi‘ah(tun).", "pandangannya tertunduk."),
    Ayah(10, 79, "يَقُوْلُوْنَ ءَاِنَّا لَمَرْدُوْدُوْنَ فِى الْحَافِرَةِۗ", "Yaqūlūna a'innā lamardūdūna fil-ḥāfirah(ti).", "Mereka (di dunia) berkata, “Apakah kita benar-benar akan dikembalikan pada kehidupan yang semula?745)"),
    Ayah(11, 79, "ءَاِذَا كُنَّا عِظَامًا نَّخِرَةً ۗ", "A'iżā kunnā ‘iẓāman nakhirah(tan).", "Apabila kita telah menjadi tulang-belulang yang hancur, apakah kita (akan dibangkitkan juga)?”"),
    Ayah(12, 79, "قَالُوْا تِلْكَ اِذًا كَرَّةٌ خَاسِرَةٌ ۘ", "Qālū tilka iżan karratun khāsirah(tun).", "Mereka berkata, “Kalau demikian, itu suatu pengembalian yang merugikan.”"),
    Ayah(13, 79, "فَاِنَّمَا هِيَ زَجْرَةٌ وَّاحِدَةٌۙ", "Fa innamā hiya zajratuw wāḥidah(tun).", "(Jangan dianggap sulit,) pengembalian itu (dilakukan) hanyalah dengan sekali tiupan."),
    Ayah(14, 79, "فَاِذَا هُمْ بِالسَّاهِرَةِۗ", "Fa iżā hum bis-sāhirah(ti).", "Seketika itu, mereka hidup kembali di bumi (yang baru)."),
    Ayah(15, 79, "هَلْ اَتٰىكَ حَدِيْثُ مُوْسٰىۘ", "Hal atāka ḥadīṡu mūsā.", "Sudah sampaikah kepadamu (Nabi Muhammad) kisah Musa?"),
    Ayah(16, 79, "اِذْ نَادٰىهُ رَبُّهٗ بِالْوَادِ الْمُقَدَّسِ طُوًىۚ", "Iż nādāhu rabbuhū bil-wādil-muqaddasi ṭuwā(n).", "(Ingatlah) ketika Tuhannya menyeru dia (Musa) di lembah suci, yaitu Lembah Tuwa,"),
    Ayah(17, 79, "اِذْهَبْ اِلٰى فِرْعَوْنَ اِنَّهٗ طَغٰىۖ", "Iżhab ilā fir‘auna innahū ṭagā.", "“Pergilah engkau kepada Fir‘aun! Sesungguhnya dia telah melampaui batas."),
    Ayah(18, 79, "فَقُلْ هَلْ لَّكَ اِلٰٓى اَنْ تَزَكّٰىۙ", "Fa qul hal laka ilā an tazakkā.", "Lalu, katakanlah (kepada Fir‘aun), ‘Adakah keinginanmu untuk menyucikan diri (dari kesesatan)"),
    Ayah(19, 79, "وَاَهْدِيَكَ اِلٰى رَبِّكَ فَتَخْشٰىۚ", "Wa ahdiyaka ilā rabbika fa takhsyā.", "dan aku akan menunjukimu ke (jalan) Tuhanmu agar engkau takut (kepada-Nya)?’”"),
    Ayah(20, 79, "فَاَرٰىهُ الْاٰيَةَ الْكُبْرٰىۖ", "Fa arāhul-āyatal-kubrā.", "Lalu, dia (Musa) memperlihatkan mukjizat yang besar kepadanya."),
    Ayah(21, 79, "فَكَذَّبَ وَعَصٰىۖ", "Fa każżaba wa ‘aṣā.", "Akan tetapi, dia (Fir‘aun) mendustakan (kerasulan) dan mendurhakai (Allah)."),
    Ayah(22, 79, "ثُمَّ اَدْبَرَ يَسْعٰىۖ", "Ṡumma adbara yas‘ā.", "Kemudian, dia berpaling seraya berusaha (menantang Musa)."),
    Ayah(23, 79, "فَحَشَرَ فَنَادٰىۖ", "Fa ḥasyara fanādā.", "Maka, dia mengumpulkan (pembesar-pembesarnya), lalu berseru (memanggil kaumnya)."),
    Ayah(24, 79, "فَقَالَ اَنَا۠ رَبُّكُمُ الْاَعْلٰىۖ", "Fa qāla ana rabbukumul-a‘lā.", "Dia berkata, “Akulah Tuhanmu yang paling tinggi.”"),
    Ayah(25, 79, "فَاَخَذَهُ اللّٰهُ نَكَالَ الْاٰخِرَةِ وَالْاُوْلٰىۗ", "Fa akhażahullāhu nakālal-ākhirati wal-ūlā.", "Maka, Allah menghukumnya dengan azab di akhirat dan (siksaan) di dunia."),
    Ayah(26, 79, "اِنَّ فِيْ ذٰلِكَ لَعِبْرَةً لِّمَنْ يَّخْشٰى ۗ ࣖ", "Inna fī żālika la‘ibratal limay yakhsyā.", "Sesungguhnya pada yang demikian itu benar-benar terdapat pelajaran bagi orang yang takut (kepada Allah)."),
    Ayah(27, 79, "ءَاَنْتُمْ اَشَدُّ خَلْقًا اَمِ السَّمَاۤءُ ۚ بَنٰىهَاۗ", "A'antum asyaddu khalqan amis-samā'u banāhā.", "Apakah penciptaan kamu yang lebih hebat ataukah langit yang telah dibangun-Nya?"),
    Ayah(28, 79, "رَفَعَ سَمْكَهَا فَسَوّٰىهَاۙ", "Rafa‘a samkahā fa sawwāhā.", "Dia telah meninggikan bangunannya, lalu menyempurnakannya."),
    Ayah(29, 79, "وَاَغْطَشَ لَيْلَهَا وَاَخْرَجَ ضُحٰىهَاۖ", "Wa agṭasya lailahā wa akhraja ḍuḥāhā.", "Dia menjadikan malamnya (gelap gulita) dan menjadikan siangnya (terang benderang)."),
    Ayah(30, 79, "وَالْاَرْضَ بَعْدَ ذٰلِكَ دَحٰىهَاۗ", "Wal-arḍa ba‘da żālika daḥāhā.", "Setelah itu, bumi Dia hamparkan (untuk dihuni)."),
    Ayah(31, 79, "اَخْرَجَ مِنْهَا مَاۤءَهَا وَمَرْعٰىهَاۖ", "Akhraja minhā mā'ahā wa mar‘āhā.", "Darinya (bumi) Dia mengeluarkan air dan (menyediakan) tempat penggembalaan."),
    Ayah(32, 79, "وَالْجِبَالَ اَرْسٰىهَاۙ", "Wal-jibāla arsāhā.", "Gunung-gunung Dia pancangkan dengan kukuh."),
    Ayah(33, 79, "مَتَاعًا لَّكُمْ وَلِاَنْعَامِكُمْۗ", "Matā‘al lakum wa li'an‘āmikum.", "(Semua itu disediakan) untuk kesenanganmu dan hewan ternakmu."),
    Ayah(34, 79, "فَاِذَا جَاۤءَتِ الطَّاۤمَّةُ الْكُبْرٰىۖ", "Fa iżā jā'atiṭ-ṭāmmatul-kubrā.", "Maka, apabila malapetaka terbesar (hari Kiamat) telah datang,"),
    Ayah(35, 79, "يَوْمَ يَتَذَكَّرُ الْاِنْسَانُ مَا سَعٰىۙ", "Yauma yatażakkarul-insānu mā sa‘ā.", "pada hari (itu) manusia teringat apa yang telah dikerjakannya"),
    Ayah(36, 79, "وَبُرِّزَتِ الْجَحِيْمُ لِمَنْ يَّرٰى", "Wa burrizatil-jaḥīmu limay yarā.", "dan (neraka) Jahim diperlihatkan dengan jelas kepada orang yang melihat(-nya)."),
    Ayah(37, 79, "فَاَمَّا مَنْ طَغٰىۖ", "Fa ammā man ṭagā.", "Adapun orang yang melampaui batas"),
    Ayah(38, 79, "وَاٰثَرَ الْحَيٰوةَ الدُّنْيَاۙ", "Wa āṡaral-ḥayātad-dun-yā.", "dan lebih mengutamakan kehidupan dunia,"),
    Ayah(39, 79, "فَاِنَّ الْجَحِيْمَ هِيَ الْمَأْوٰىۗ", "Fa innal-jaḥīma hiyal-ma'wā.", "sesungguhnya (neraka) Jahimlah tempat tinggal(-nya)."),
    Ayah(40, 79, "وَاَمَّا مَنْ خَافَ مَقَامَ رَبِّهٖ وَنَهَى النَّفْسَ عَنِ الْهَوٰىۙ", "Wa ammā man khāfa maqāma rabbihī wa nahan-nafsa ‘anil-hawā.", "Adapun orang-orang yang takut pada kebesaran Tuhannya dan menahan diri dari (keinginan) hawa nafsunya,"),
    Ayah(41, 79, "فَاِنَّ الْجَنَّةَ هِيَ الْمَأْوٰىۗ", "Fa innal-jannata hiyal-ma'wā.", "sesungguhnya surgalah tempat tinggal(-nya)."),
    Ayah(42, 79, "يَسْـَٔلُوْنَكَ عَنِ السَّاعَةِ اَيَّانَ مُرْسٰىهَاۗ", "Yas'alūnaka ‘anis-sā‘ati ayyāna mursāhā.", "Mereka (orang-orang kafir) bertanya kepadamu (Nabi Muhammad) tentang hari Kiamat, “Kapankah terjadinya?”"),
    Ayah(43, 79, "فِيْمَ اَنْتَ مِنْ ذِكْرٰىهَاۗ", "Fīma anta min żikrāhā.", "Untuk apa engkau perlu menyebutkan (waktu)-nya?"),
    Ayah(44, 79, "اِلٰى رَبِّكَ مُنْتَهٰىهَاۗ", "Ilā rabbika muntahāhā.", "Kepada Tuhanmulah (dikembalikan) kesudahan (ketentuan waktu)-nya."),
    Ayah(45, 79, "اِنَّمَآ اَنْتَ مُنْذِرُ مَنْ يَّخْشٰىهَاۗ", "Innamā anta munżiru may yakhsyāhā.", "Engkau (Nabi Muhammad) hanyalah pemberi peringatan kepada siapa yang takut padanya (hari Kiamat)."),
    Ayah(46, 79, "كَاَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوْٓا اِلَّا عَشِيَّةً اَوْ ضُحٰىهَا ࣖ", "Ka'annahum yauma yaraunahā lam yalbaṡū illā ‘asyiyyatan au ḍuḥāhā.", "Pada hari ketika melihatnya (hari Kiamat itu), mereka merasa seakan-akan hanya (sebentar) tinggal (di dunia) pada waktu petang atau pagi."),
)

internal fun quranFullAyahs80(): List<Ayah> = listOf(
    Ayah(1, 80, "عَبَسَ وَتَوَلّٰىٓۙ", "‘Abasa wa tawallā.", "Dia (Nabi Muhammad) berwajah masam dan berpaling"),
    Ayah(2, 80, "اَنْ جَاۤءَهُ الْاَعْمٰىۗ", "An jā'ahul-a‘mā.", "karena seorang tunanetra (Abdullah bin Ummi Maktum) telah datang kepadanya."),
    Ayah(3, 80, "وَمَا يُدْرِيْكَ لَعَلَّهٗ يَزَّكّٰىٓۙ", "Wa mā yudrīka la‘allahū yazzakkā.", "Tahukah engkau (Nabi Muhammad) boleh jadi dia ingin menyucikan dirinya (dari dosa)"),
    Ayah(4, 80, "اَوْ يَذَّكَّرُ فَتَنْفَعَهُ الذِّكْرٰىۗ", "Au yażżakkaru fatanfa‘ahuż-żikrā.", "atau dia (ingin) mendapatkan pengajaran sehingga pengajaran itu bermanfaat baginya?"),
    Ayah(5, 80, "اَمَّا مَنِ اسْتَغْنٰىۙ", "Ammā manistagnā.", "Adapun orang yang merasa dirinya serba cukup (para pembesar Quraisy),"),
    Ayah(6, 80, "فَاَنْتَ لَهٗ تَصَدّٰىۗ", "Fa anta lahū taṣaddā.", "engkau (Nabi Muhammad) memberi perhatian kepadanya."),
    Ayah(7, 80, "وَمَا عَلَيْكَ اَلَّا يَزَّكّٰىۗ", "Wa mā ‘alaika allā yazzakkā.", "Padahal, tidak ada (cela) atasmu kalau dia tidak menyucikan diri (beriman)."),
    Ayah(8, 80, "وَاَمَّا مَنْ جَاۤءَكَ يَسْعٰىۙ", "Wa ammā man jā'aka yas‘ā.", "Adapun orang yang datang kepadamu dengan bersegera (untuk mendapatkan pengajaran),"),
    Ayah(9, 80, "وَهُوَ يَخْشٰىۙ", "Wa huwa yakhsyā.", "sedangkan dia takut (kepada Allah),"),
    Ayah(10, 80, "فَاَنْتَ عَنْهُ تَلَهّٰىۚ", "Fa anta ‘anhu talahhā.", "malah engkau (Nabi Muhammad) abaikan."),
    Ayah(11, 80, "كَلَّآ اِنَّهَا تَذْكِرَةٌ ۚ", "Kallā innahā tażkirah(tun).", "Sekali-kali jangan (begitu)! Sesungguhnya (ajaran Allah) itu merupakan peringatan."),
    Ayah(12, 80, "فَمَنْ شَاۤءَ ذَكَرَهٗ ۘ", "Faman syā'a żakarah(ū).", "Siapa yang menghendaki tentulah akan memperhatikannya"),
    Ayah(13, 80, "فِيْ صُحُفٍ مُّكَرَّمَةٍۙ", "Fī ṣuḥufim mukarrmah(tin).", "di dalam suhuf yang dimuliakan (di sisi Allah),"),
    Ayah(14, 80, "مَّرْفُوْعَةٍ مُّطَهَّرَةٍ ۢ ۙ", "Marfū‘atim muṭahharah(tin).", "yang ditinggikan (kedudukannya) lagi disucikan"),
    Ayah(15, 80, "بِاَيْدِيْ سَفَرَةٍۙ", "Bi'aidī safarah(tin).", "di tangan para utusan (malaikat)"),
    Ayah(16, 80, "كِرَامٍۢ بَرَرَةٍۗ", "Kirāmim bararah(tin).", "yang mulia lagi berbudi."),
    Ayah(17, 80, "قُتِلَ الْاِنْسَانُ مَآ اَكْفَرَهٗۗ", "Qutilal-insānu mā akfarah(ū).", "Celakalah manusia! Alangkah kufur dia!"),
    Ayah(18, 80, "مِنْ اَيِّ شَيْءٍ خَلَقَهٗۗ", "Min ayyi syai'in khalaqah(ū).", "Dari apakah Dia menciptakannya?"),
    Ayah(19, 80, "مِنْ نُّطْفَةٍۗ خَلَقَهٗ فَقَدَّرَهٗۗ", "Min nuṭfah(tin), khalaqahū fa qaddarah(ū).", "Dia menciptakannya dari setetes mani, lalu menentukan (takdir)-nya."),
    Ayah(20, 80, "ثُمَّ السَّبِيْلَ يَسَّرَهٗۙ", "Ṡummas-sabīla yassarah(ū).", "Kemudian, jalannya Dia mudahkan.746)"),
    Ayah(21, 80, "ثُمَّ اَمَاتَهٗ فَاَقْبَرَهٗۙ", "Ṡumma amātahū fa aqbarah(ū).", "Kemudian, Dia mematikannya lalu menguburkannya."),
    Ayah(22, 80, "ثُمَّ اِذَا شَاۤءَ اَنْشَرَهٗۗ", "Ṡumma iżā syā'a ansyarah(ū).", "Kemudian, jika menghendaki, Dia membangkitkannya kembali."),
    Ayah(23, 80, "كَلَّا لَمَّا يَقْضِ مَآ اَمَرَهٗۗ", "Kallā lammā yaqḍi mā amarah(ū).", "Sekali-kali jangan (begitu)! Dia (manusia) itu belum melaksanakan apa yang Dia (Allah) perintahkan kepadanya."),
    Ayah(24, 80, "فَلْيَنْظُرِ الْاِنْسَانُ اِلٰى طَعَامِهٖٓ ۙ", "Falyanẓuril-insānu ilā ṭa‘āmih(ī).", "Maka, hendaklah manusia itu memperhatikan makanannya."),
    Ayah(25, 80, "اَنَّا صَبَبْنَا الْمَاۤءَ صَبًّاۙ", "Annā ṣababnal-mā'a ṣabbā(n).", "Sesungguhnya Kami telah mencurahkan air (dari langit) dengan berlimpah."),
    Ayah(26, 80, "ثُمَّ شَقَقْنَا الْاَرْضَ شَقًّاۙ", "Ṡumma syaqaqnal-arḍa syaqqā(n).", "Kemudian, Kami belah bumi dengan sebaik-baiknya."),
    Ayah(27, 80, "فَاَنْۢبَتْنَا فِيْهَا حَبًّاۙ", "Fa'ambatnā fīhā ḥabbā(n).", "Lalu, Kami tumbuhkan padanya biji-bijian,"),
    Ayah(28, 80, "وَّعِنَبًا وَّقَضْبًاۙ", "Wa ‘inabaw wa qaḍbā(n).", "anggur, sayur-sayuran,"),
    Ayah(29, 80, "وَّزَيْتُوْنًا وَّنَخْلًاۙ", "Wa zaitūnaw wa nakhlā(n).", "zaitun, pohon kurma,"),
    Ayah(30, 80, "وَّحَدَاۤىِٕقَ غُلْبًا", "Wa ḥadā'iqa gulbā(n).", "kebun-kebun (yang) rindang,"),
    Ayah(31, 80, "وَفَاكِهَةً وَّاَبًّا", "Wa fākihataw wa abbā(n).", "buah-buahan, dan rerumputan."),
    Ayah(32, 80, "مَتَاعًا لَّكُمْ وَلِاَنْعَامِكُمْۗ", "Matā‘al lakum wa li'an‘āmikum.", "(Semua itu disediakan) untuk kesenanganmu dan hewan-hewan ternakmu."),
    Ayah(33, 80, "فَاِذَا جَاۤءَتِ الصَّاۤخَّةُ ۖ", "Fa iżā jā'atiṣ-ṣākhkhah(tu).", "Maka, apabila datang suara yang memekakkan (dari tiupan sangkakala),"),
    Ayah(34, 80, "يَوْمَ يَفِرُّ الْمَرْءُ مِنْ اَخِيْهِۙ", "Yauma yafirrul-mar'u min akhīh(i).", "pada hari itu manusia lari dari saudaranya,"),
    Ayah(35, 80, "وَاُمِّهٖ وَاَبِيْهِۙ", "Wa ummihī wa abīh(i).", "(dari) ibu dan bapaknya,"),
    Ayah(36, 80, "وَصَاحِبَتِهٖ وَبَنِيْهِۗ", "Wa ṣāḥibatihī wa banīh(i).", "serta (dari) istri dan anak-anaknya."),
    Ayah(37, 80, "لِكُلِّ امْرِئٍ مِّنْهُمْ يَوْمَىِٕذٍ شَأْنٌ يُّغْنِيْهِۗ", "Likullimri'im minhum yauma'iżin sya'nuy yugnīh(i).", "Setiap orang dari mereka pada hari itu mempunyai urusan yang menyibukkannya."),
    Ayah(38, 80, "وُجُوْهٌ يَّوْمَىِٕذٍ مُّسْفِرَةٌۙ", "Wujūhuy yauma'iżim musfirah(tun).", "Pada hari itu ada wajah-wajah yang berseri-seri,"),
    Ayah(39, 80, "ضَاحِكَةٌ مُّسْتَبْشِرَةٌ ۚ", "Ḍāḥikatum mustabsyirah(tun).", "tertawa lagi gembira ria."),
    Ayah(40, 80, "وَوُجُوْهٌ يَّوْمَىِٕذٍ عَلَيْهَا غَبَرَةٌۙ", "Wa wujūhuy yauma'iżin ‘alaihā gabarah(tun).", "Pada hari itu ada (pula) wajah-wajah yang tertutup debu (suram)"),
    Ayah(41, 80, "تَرْهَقُهَا قَتَرَةٌ ۗ", "Tarhaquhā qatarah(tun).", "dan tertutup oleh kegelapan (ditimpa kehinaan dan kesusahan)."),
    Ayah(42, 80, "اُولٰۤىِٕكَ هُمُ الْكَفَرَةُ الْفَجَرَةُ ࣖ", "Ulā'ika humul-kafaratul-fajarah(tu).", "Mereka itulah orang-orang kafir lagi para pendurhaka."),
)

internal fun quranFullAyahs81(): List<Ayah> = listOf(
    Ayah(1, 81, "اِذَا الشَّمْسُ كُوِّرَتْۖ", "Iżasy-syamsu kuwwirat.", "Apabila matahari digulung,"),
    Ayah(2, 81, "وَاِذَا النُّجُوْمُ انْكَدَرَتْۖ", "Wa iżan-nujūmunkadarat.", "apabila bintang-bintang berjatuhan,"),
    Ayah(3, 81, "وَاِذَا الْجِبَالُ سُيِّرَتْۖ", "Wa iżal-jibālu suyyirat.", "apabila gunung-gunung dihancurkan,"),
    Ayah(4, 81, "وَاِذَا الْعِشَارُ عُطِّلَتْۖ", "Wa iżal-‘isyāru ‘uṭṭilat.", "apabila unta-unta yang bunting ditinggalkan (tidak terurus),"),
    Ayah(5, 81, "وَاِذَا الْوُحُوْشُ حُشِرَتْۖ", "Wa iżal-wuḥūsy ḥusyirat.", "apabila binatang-binatang liar dikumpulkan,"),
    Ayah(6, 81, "وَاِذَا الْبِحَارُ سُجِّرَتْۖ", "Wa iżal-biḥāru sujjirat.", "apabila lautan dipanaskan,"),
    Ayah(7, 81, "وَاِذَا النُّفُوْسُ زُوِّجَتْۖ", "Wa iżan-nufūsu zuwwijat.", "apabila roh-roh dipertemukan (dengan tubuh),"),
    Ayah(8, 81, "وَاِذَا الْمَوْءٗدَةُ سُىِٕلَتْۖ", "Wa iżal-mau'ūdatu su'ilat.", "apabila bayi-bayi perempuan yang dikubur hidup-hidup ditanya,"),
    Ayah(9, 81, "بِاَيِّ ذَنْۢبٍ قُتِلَتْۚ", "Bi'ayyi żambin qutilat.", "“Karena dosa apa dia dibunuh,”"),
    Ayah(10, 81, "وَاِذَا الصُّحُفُ نُشِرَتْۖ", "Wa iżaṣ-ṣuḥufu nusyirat.", "apabila lembaran-lembaran (catatan amal) telah dibuka lebar-lebar,"),
    Ayah(11, 81, "وَاِذَا السَّمَاۤءُ كُشِطَتْۖ", "Wa iżas-samā'u kusyiṭat.", "apabila langit dilenyapkan,"),
    Ayah(12, 81, "وَاِذَا الْجَحِيْمُ سُعِّرَتْۖ", "Wa iżal-jaḥīmu su‘‘irat.", "apabila (neraka) Jahim dinyalakan,"),
    Ayah(13, 81, "وَاِذَا الْجَنَّةُ اُزْلِفَتْۖ", "Wa iżal-jannatu uzlifat.", "dan apabila surga didekatkan,"),
    Ayah(14, 81, "عَلِمَتْ نَفْسٌ مَّآ اَحْضَرَتْۗ", "‘Alimat nafsum mā aḥḍarat.", "setiap jiwa akan mengetahui apa yang telah dikerjakannya."),
    Ayah(15, 81, "فَلَآ اُقْسِمُ بِالْخُنَّسِۙ", "Falā uqsimu bil-khunnas(i).", "Aku bersumpah demi bintang-bintang"),
    Ayah(16, 81, "الْجَوَارِ الْكُنَّسِۙ", "Al-jawāril-kunnas(i).", "yang beredar lagi terbenam,"),
    Ayah(17, 81, "وَالَّيْلِ اِذَا عَسْعَسَۙ", "Wal-laili iżā ‘as‘as(a).", "demi malam apabila telah larut,"),
    Ayah(18, 81, "وَالصُّبْحِ اِذَا تَنَفَّسَۙ", "Waṣ-ṣubḥi iżā tanaffas(a).", "demi subuh apabila (fajar) telah menyingsing,"),
    Ayah(19, 81, "اِنَّهٗ لَقَوْلُ رَسُوْلٍ كَرِيْمٍۙ", "Innahū laqaulu rasūlin karīm(in).", "sesungguhnya (Al-Qur’an) itu benar-benar firman (Allah yang dibawa oleh) utusan yang mulia (Jibril)"),
    Ayah(20, 81, "ذِيْ قُوَّةٍ عِنْدَ ذِى الْعَرْشِ مَكِيْنٍۙ", "Żī quwwatin ‘inda żil-‘arsyi makīn(in).", "yang memiliki kekuatan dan kedudukan tinggi di sisi (Allah) yang memiliki ʻArasy,"),
    Ayah(21, 81, "مُّطَاعٍ ثَمَّ اَمِيْنٍۗ", "Muṭā‘in ṡamma amīn(in).", "yang di sana (Jibril) ditaati lagi dipercaya."),
    Ayah(22, 81, "وَمَا صَاحِبُكُمْ بِمَجْنُوْنٍۚ", "Wa mā ṣāḥibukum bimajnūn(in).", "Temanmu (Nabi Muhammad) itu bukanlah orang gila."),
    Ayah(23, 81, "وَلَقَدْ رَاٰهُ بِالْاُفُقِ الْمُبِيْنِۚ", "Wa laqad ra'āhu bil-ufuqil-mubīn(i).", "Sungguh, dia (Nabi Muhammad) benar-benar telah melihatnya (Jibril) di ufuk yang terang."),
    Ayah(24, 81, "وَمَا هُوَ عَلَى الْغَيْبِ بِضَنِيْنٍۚ", "Wa mā huwa ‘alal-gaibi biḍanīn(in).", "Dia (Nabi Muhammad) bukanlah seorang yang kikir (enggan) untuk menerangkan yang gaib."),
    Ayah(25, 81, "وَمَا هُوَ بِقَوْلِ شَيْطٰنٍ رَّجِيْمٍۚ", "Wa mā huwa biqauli syaiṭānir rajīm(in).", "(Al-Qur’an) itu bukanlah perkataan setan yang terkutuk."),
    Ayah(26, 81, "فَاَيْنَ تَذْهَبُوْنَۗ", "Fa aina tażhabūn(a).", "Maka, ke manakah kamu akan pergi?747)"),
    Ayah(27, 81, "اِنْ هُوَ اِلَّا ذِكْرٌ لِّلْعٰلَمِيْنَۙ", "In huwa illā żikrul lil-‘ālamīn(a).", "(Al-Qur’an) itu tidak lain, kecuali peringatan bagi semesta alam,"),
    Ayah(28, 81, "لِمَنْ شَاۤءَ مِنْكُمْ اَنْ يَّسْتَقِيْمَۗ", "Liman syā'a minkum ay yastaqīm(a).", "(yaitu) bagi siapa di antaramu yang hendak menempuh jalan yang lurus."),
    Ayah(29, 81, "وَمَا تَشَاۤءُوْنَ اِلَّآ اَنْ يَّشَاۤءَ اللّٰهُ رَبُّ الْعٰلَمِيْنَ ࣖ", "Wa mā tasyā'ūna illā ay yasyā'allāhu rabbul-‘ālamīn(a).", "Kamu tidak dapat berkehendak, kecuali apabila dikehendaki Allah, Tuhan semesta alam."),
)

internal fun quranFullAyahs82(): List<Ayah> = listOf(
    Ayah(1, 82, "اِذَا السَّمَاۤءُ انْفَطَرَتْۙ", "Iżas-samā'unfaṭarat.", "Apabila langit terbelah,"),
    Ayah(2, 82, "وَاِذَا الْكَوَاكِبُ انْتَثَرَتْۙ", "Wa iżal-kawākibuntaṡarat.", "apabila bintang-bintang jatuh berserakan,"),
    Ayah(3, 82, "وَاِذَا الْبِحَارُ فُجِّرَتْۙ", "Wa iżal-biḥāru fujjirat.", "apabila lautan diluapkan,"),
    Ayah(4, 82, "وَاِذَا الْقُبُوْرُ بُعْثِرَتْۙ", "Wa iżal-qubūru bu‘ṡirat.", "dan apabila kuburan-kuburan dibongkar,"),
    Ayah(5, 82, "عَلِمَتْ نَفْسٌ مَّا قَدَّمَتْ وَاَخَّرَتْۗ", "‘Alimat nafsum mā qaddamat wa akhkharat.", "setiap jiwa akan mengetahui apa yang telah dikerjakan dan yang dilalaikan(-nya)."),
    Ayah(6, 82, "يٰٓاَيُّهَا الْاِنْسَانُ مَا غَرَّكَ بِرَبِّكَ الْكَرِيْمِۙ", "Yā ayyuhal-insānu mā garraka birabbikal-karīm(i).", "Wahai manusia, apakah yang telah memperdayakanmu (berbuat durhaka) terhadap Tuhanmu Yang Mahamulia,"),
    Ayah(7, 82, "الَّذِيْ خَلَقَكَ فَسَوّٰىكَ فَعَدَلَكَۙ", "Allażī khalaqaka fa sawwāka fa ‘adalak(a).", "yang telah menciptakanmu lalu menyempurnakan kejadianmu dan menjadikan (susunan tubuh)-mu seimbang?"),
    Ayah(8, 82, "فِيْٓ اَيِّ صُوْرَةٍ مَّا شَاۤءَ رَكَّبَكَۗ", "Fī ayyi ṣūratim mā syā'a rakkabak(a).", "Dalam bentuk apa saja yang dikehendaki, Dia menyusun (tubuh)-mu."),
    Ayah(9, 82, "كَلَّا بَلْ تُكَذِّبُوْنَ بِالدِّيْنِۙ", "Kallā bal tukażżibūna bid-dīn(i).", "Jangan sekali-kali begitu! Bahkan, kamu mendustakan hari Pembalasan."),
    Ayah(10, 82, "وَاِنَّ عَلَيْكُمْ لَحٰفِظِيْنَۙ", "Wa inna ‘alaikum laḥāfiẓīn(a).", "Sesungguhnya bagi kamu ada (malaikat-malaikat) pengawas"),
    Ayah(11, 82, "كِرَامًا كٰتِبِيْنَۙ", "Kirāman kātibīn(a).", "yang mulia (di sisi Allah) dan mencatat (amal perbuatanmu)."),
    Ayah(12, 82, "يَعْلَمُوْنَ مَا تَفْعَلُوْنَ", "Ya‘lamūna mā taf‘alūn(a).", "Mereka mengetahui apa yang kamu kerjakan."),
    Ayah(13, 82, "اِنَّ الْاَبْرَارَ لَفِيْ نَعِيْمٍۙ", "Innal-abrāra lafī na‘īm(in).", "Sesungguhnya orang-orang yang berbakti benar-benar berada dalam (surga yang penuh) kenikmatan."),
    Ayah(14, 82, "وَّاِنَّ الْفُجَّارَ لَفِيْ جَحِيْمٍ", "Wa innal-fujjāra lafī jaḥīm(in).", "Sesungguhnya orang-orang yang durhaka benar-benar berada dalam (neraka) Jahim."),
    Ayah(15, 82, "يَصْلَوْنَهَا يَوْمَ الدِّيْنِ", "Yaṣlaunahā yaumad-dīn(i).", "Mereka memasukinya pada hari Pembalasan."),
    Ayah(16, 82, "وَمَا هُمْ عَنْهَا بِغَاۤىِٕبِيْنَۗ", "Wa mā hum ‘anhā bigā'ibīn(a).", "Mereka tidak mungkin keluar dari (neraka) itu."),
    Ayah(17, 82, "وَمَآ اَدْرٰىكَ مَا يَوْمُ الدِّيْنِۙ", "Wa mā adrāka mā yaumud-dīn(i).", "Tahukah engkau apakah hari Pembalasan itu?"),
    Ayah(18, 82, "ثُمَّ مَآ اَدْرٰىكَ مَا يَوْمُ الدِّيْنِۗ", "Ṡumma mā adrāka mā yaumud-dīn(i).", "Kemudian, tahukah engkau apakah hari Pembalasan itu?"),
    Ayah(19, 82, "يَوْمَ لَا تَمْلِكُ نَفْسٌ لِّنَفْسٍ شَيْـًٔا ۗوَالْاَمْرُ يَوْمَىِٕذٍ لِّلّٰهِ ࣖ", "Yauma lā tamliku nafsul linafsin syai'ā(n), wal-amru yauma'iżil lillāh(i).", "(Itulah) hari (ketika) seseorang tidak berdaya (menolong) orang lain sedikit pun. Segala urusan pada hari itu adalah milik Allah."),
)

internal fun quranFullAyahs83(): List<Ayah> = listOf(
    Ayah(1, 83, "وَيْلٌ لِّلْمُطَفِّفِيْنَۙ", "Wailul lil-muṭaffifīn(a).", "Celakalah orang-orang yang curang (dalam menakar dan menimbang)!"),
    Ayah(2, 83, "الَّذِيْنَ اِذَا اكْتَالُوْا عَلَى النَّاسِ يَسْتَوْفُوْنَۖ", "Allażīna iżaktālū ‘alan-nāsi yastaufūn(a).", "(Mereka adalah) orang-orang yang apabila menerima takaran dari orang lain, mereka minta dipenuhi."),
    Ayah(3, 83, "وَاِذَا كَالُوْهُمْ اَوْ وَّزَنُوْهُمْ يُخْسِرُوْنَۗ", "Wa iżā kālūhum au wazanūhum yukhsirūn(a).", "(Sebaliknya,) apabila mereka menakar atau menimbang untuk orang lain, mereka kurangi."),
    Ayah(4, 83, "اَلَا يَظُنُّ اُولٰۤىِٕكَ اَنَّهُمْ مَّبْعُوْثُوْنَۙ", "Alā yaẓunnu ulā'ika annahum mab‘ūṡūn(a).", "Tidakkah mereka mengira (bahwa) sesungguhnya mereka akan dibangkitkan"),
    Ayah(5, 83, "لِيَوْمٍ عَظِيْمٍۙ", "Liyaumin ‘aẓīm(in).", "pada suatu hari yang besar (Kiamat),"),
    Ayah(6, 83, "يَّوْمَ يَقُوْمُ النَّاسُ لِرَبِّ الْعٰلَمِيْنَۗ", "Yauma yaqūmun-nāsu lirabbil-‘ālamīn(a).", "(yaitu) hari (ketika) manusia bangkit menghadap Tuhan seluruh alam?"),
    Ayah(7, 83, "كَلَّآ اِنَّ كِتٰبَ الْفُجَّارِ لَفِيْ سِجِّيْنٍۗ", "Kallā inna kitābal-fujjāri lafī sijjīn(in).", "Jangan sekali-kali begitu! Sesungguhnya catatan orang yang durhaka benar-benar (tersimpan) dalam Sijjīn.748)"),
    Ayah(8, 83, "وَمَآ اَدْرٰىكَ مَا سِجِّيْنٌۗ", "Wa mā adrāka mā sijjīn(un).", "Tahukah engkau apakah Sijjīnitu?"),
    Ayah(9, 83, "كِتٰبٌ مَّرْقُوْمٌۗ", "Kitābum marqūm(un).", "(Ia adalah) kitab yang berisi catatan (amal)."),
    Ayah(10, 83, "وَيْلٌ يَّوْمَىِٕذٍ لِّلْمُكَذِّبِيْنَۙ", "Wailuy yauma'iżil lil-mukażżibīn(a).", "Celakalah pada hari itu bagi para pendusta,"),
    Ayah(11, 83, "الَّذِيْنَ يُكَذِّبُوْنَ بِيَوْمِ الدِّيْنِۗ", "Allażīna yukażżibūna biyaumid-dīn(i).", "yaitu orang-orang yang mendustakan hari Pembalasan."),
    Ayah(12, 83, "وَمَا يُكَذِّبُ بِهٖٓ اِلَّا كُلُّ مُعْتَدٍ اَثِيْمٍۙ", "Wa mā yukażżibu bihī illā kullu mu‘tadin aṡīm(in).", "Tidak ada yang mendustakannya, kecuali setiap orang yang melampaui batas lagi sangat berdosa."),
    Ayah(13, 83, "اِذَا تُتْلٰى عَلَيْهِ اٰيٰتُنَا قَالَ اَسَاطِيْرُ الْاَوَّلِيْنَۗ", "Iżā tutlā ‘alaihi āyātunā qāla asāṭīrul-awwalīn(a).", "Apabila dibacakan kepadanya ayat-ayat Kami, dia berkata, “(Itu adalah) dongeng orang-orang dahulu.”"),
    Ayah(14, 83, "كَلَّا بَلْ ۜرَانَ عَلٰى قُلُوْبِهِمْ مَّا كَانُوْا يَكْسِبُوْنَ", "Kallā bal…rāna ‘alā qulūbihim mā kānū yaksibūn(a).", "Sekali-kali tidak! Bahkan, apa yang selalu mereka kerjakan itu telah menutupi hati mereka."),
    Ayah(15, 83, "كَلَّآ اِنَّهُمْ عَنْ رَّبِّهِمْ يَوْمَىِٕذٍ لَّمَحْجُوْبُوْنَۗ", "Kallā innahum ‘ar rabbihim yauma'iżil lamaḥjūbūn(a).", "Sekali-kali tidak!749) Sesungguhnya mereka pada hari itu benar-benar terhalang dari (rahmat) Tuhannya."),
    Ayah(16, 83, "ثُمَّ اِنَّهُمْ لَصَالُوا الْجَحِيْمِۗ", "Ṡumma innahum laṣālul-jaḥīm(i).", "Sesungguhnya mereka kemudian benar-benar masuk (neraka) Jahim."),
    Ayah(17, 83, "ثُمَّ يُقَالُ هٰذَا الَّذِيْ كُنْتُمْ بِهٖ تُكَذِّبُوْنَۗ", "Ṡumma yuqālu hāżal-lażī kuntum bihī tukażżibūn(a).", "Lalu dikatakan (kepada mereka), “Inilah (azab) yang selalu kamu dustakan.”"),
    Ayah(18, 83, "كَلَّآ اِنَّ كِتٰبَ الْاَبْرَارِ لَفِيْ عِلِّيِّيْنَۗ", "Kallā inna kitābal-abrāri lafī ‘illiyyīn(a).", "Sekali-kali tidak! Sesungguhnya catatan orang-orang yang berbakti benar-benar tersimpan dalam ‘Illiyyīn.750)"),
    Ayah(19, 83, "وَمَآ اَدْرٰىكَ مَا عِلِّيُّوْنَۗ", "Wa mā adrāka mā ‘illiyyūn(a).", "Tahukah engkau apakah ‘Illiyyīnitu?"),
    Ayah(20, 83, "كِتٰبٌ مَّرْقُوْمٌۙ", "Kitābum marqūm(un).", "(Itulah) kitab yang berisi catatan (amal)"),
    Ayah(21, 83, "يَّشْهَدُهُ الْمُقَرَّبُوْنَۗ", "Yasyhaduhul-muqarrabūn(a).", "yang disaksikan oleh (malaikat-malaikat) yang didekatkan (kepada Allah)."),
    Ayah(22, 83, "اِنَّ الْاَبْرَارَ لَفِيْ نَعِيْمٍۙ", "Innal-abrāra lafī na‘īm(in).", "Sesungguhnya orang-orang yang berbakti benar-benar berada dalam (surga yang penuh) kenikmatan."),
    Ayah(23, 83, "عَلَى الْاَرَاۤىِٕكِ يَنْظُرُوْنَۙ", "‘Alal-arā'iki yanẓurūn(a).", "Mereka (duduk) di atas dipan-dipan (sambil) melepas pandangan."),
    Ayah(24, 83, "تَعْرِفُ فِيْ وُجُوْهِهِمْ نَضْرَةَ النَّعِيْمِۚ", "Ta‘rifu fī wujūhihim naḍratan na‘īm(i).", "Engkau dapat mengetahui pada wajah mereka gemerlapnya kenikmatan."),
    Ayah(25, 83, "يُسْقَوْنَ مِنْ رَّحِيْقٍ مَّخْتُوْمٍۙ", "Yusqauna mir raḥīqim makhtūm(in).", "Mereka diberi minum dari khamar murni (tidak memabukkan) yang (tempatnya) masih diberi lak (sebagai jaminan keasliannya)."),
    Ayah(26, 83, "خِتٰمُهٗ مِسْكٌ ۗوَفِيْ ذٰلِكَ فَلْيَتَنَافَسِ الْمُتَنٰفِسُوْنَۗ", "Khitāmuhū misk(un), wa fī żālika falyatanāfasil-mutanāfisūn(a).", "Laknya terbuat dari kasturi. Untuk (mendapatkan) yang demikian itu hendaknya orang berlomba-lomba."),
    Ayah(27, 83, "وَمِزَاجُهٗ مِنْ تَسْنِيْمٍۙ", "Wa mizājuhū min tasnīm(in).", "Campurannya terbuat dari tasnīm,"),
    Ayah(28, 83, "عَيْنًا يَّشْرَبُ بِهَا الْمُقَرَّبُوْنَۗ", "‘Ainay yasyrabu bihal-muqarrabūn(a).", "(yaitu) mata air yang diminum oleh mereka yang didekatkan (kepada Allah)."),
    Ayah(29, 83, "اِنَّ الَّذِيْنَ اَجْرَمُوْا كَانُوْا مِنَ الَّذِيْنَ اٰمَنُوْا يَضْحَكُوْنَۖ", "Innal-lażīna ajramū kānū minal-lażīna āmanū yaḍḥakūn(a).", "Sesungguhnya orang-orang yang berdosa adalah mereka yang dahulu selalumentertawakan orang-orang yang beriman."),
    Ayah(30, 83, "وَاِذَا مَرُّوْا بِهِمْ يَتَغَامَزُوْنَۖ", "Wa iżā marrū bihim yatagāmazūn(a).", "Apabila mereka (orang-orang yang beriman) melintas di hadapan mereka, mereka saling mengedip-ngedipkan matanya."),
    Ayah(31, 83, "وَاِذَا انْقَلَبُوْٓا اِلٰٓى اَهْلِهِمُ انْقَلَبُوْا فَكِهِيْنَۖ", "Wa iżanqalabū ilā ahlihimunqalabū fakihīn(a).", "Apabila kembali kepada kaumnya, mereka kembali dengan gembira ria (dan sombong)."),
    Ayah(32, 83, "وَاِذَا رَاَوْهُمْ قَالُوْٓا اِنَّ هٰٓؤُلَاۤءِ لَضَاۤلُّوْنَۙ", "Wa iżā ra'auhum qālū inna hā'ulā'i laḍāllūn(a).", "Apabila melihat (orang-orang mukmin), mereka mengatakan, “Sesungguhnya mereka benar-benar orang-orang sesat,”"),
    Ayah(33, 83, "وَمَآ اُرْسِلُوْا عَلَيْهِمْ حٰفِظِيْنَۗ", "Wa mā ursilū ‘alaihim ḥāfiẓīn(a).", "padahal mereka (orang-orang yang berdosa itu) tidak diutus sebagai penjaga (orang-orang mukmin)."),
    Ayah(34, 83, "فَالْيَوْمَ الَّذِيْنَ اٰمَنُوْا مِنَ الْكُفَّارِ يَضْحَكُوْنَۙ", "Fal-yaumal-lażīna āmanū minal kuffāri yaḍḥakūn(a).", "Pada hari ini (hari Kiamat), orang-orang yang berimanlah yang mentertawakan orang-orang kafir."),
    Ayah(35, 83, "عَلَى الْاَرَاۤىِٕكِ يَنْظُرُوْنَۗ", "‘Alal-arā'iki yanẓurūn(a).", "Mereka (duduk) di atas dipan-dipan (sambil) melepas pandangan."),
    Ayah(36, 83, "هَلْ ثُوِّبَ الْكُفَّارُ مَا كَانُوْا يَفْعَلُوْنَ ࣖ", "Hal ṡuwwibal-kuffāru mā kānū yaf‘alūn(a).", "Apakah orang-orang kafir itu telah diberi balasan (hukuman) terhadap apa yang selalu mereka perbuat?"),
)

internal fun quranFullAyahs84(): List<Ayah> = listOf(
    Ayah(1, 84, "اِذَا السَّمَاۤءُ انْشَقَّتْۙ", "Iżas-samā'unsyaqqat.", "Apabila langit terbelah"),
    Ayah(2, 84, "وَاَذِنَتْ لِرَبِّهَا وَحُقَّتْۙ", "Wa ażinat lirabbihā wa ḥuqqat.", "serta patuh kepada Tuhannya dan sudah semestinya patuh."),
    Ayah(3, 84, "وَاِذَا الْاَرْضُ مُدَّتْۙ", "Wa iẓal-arḍu muddat.", "Apabila bumi diratakan,"),
    Ayah(4, 84, "وَاَلْقَتْ مَا فِيْهَا وَتَخَلَّتْۙ", "Wa alqat mā fīhā wa takhallat.", "memuntahkan apa yang ada di dalamnya dan menjadi kosong,"),
    Ayah(5, 84, "وَاَذِنَتْ لِرَبِّهَا وَحُقَّتْۗ", "Wa ażinat lirabbihā wa ḥuqqat.", "serta patuh kepada Tuhannya, dan sudah semestinya patuh."),
    Ayah(6, 84, "يٰٓاَيُّهَا الْاِنْسَانُ اِنَّكَ كَادِحٌ اِلٰى رَبِّكَ كَدْحًا فَمُلٰقِيْهِۚ", "Yā ayyuhal-insānu innaka kādiḥun ilā rabbika kadḥan fa mulāqīh(i).", "Wahai manusia, sesungguhnya engkau telah bekerja keras menuju (pertemuan dengan) Tuhanmu. Maka, engkau pasti menemui-Nya.751)"),
    Ayah(7, 84, "فَاَمَّا مَنْ اُوْتِيَ كِتٰبَهٗ بِيَمِيْنِهٖۙ", "Fa ammā man ūtiya kitābahū biyamīnih(ī).", "Adapun orang yang catatannya diberikan dari sebelah kanannya,"),
    Ayah(8, 84, "فَسَوْفَ يُحَاسَبُ حِسَابًا يَّسِيْرًاۙ", "Fa saufa yuḥāsabu ḥisābay yasīrā(n).", "dia akan dihisab dengan pemeriksaan yang mudah"),
    Ayah(9, 84, "وَّيَنْقَلِبُ اِلٰٓى اَهْلِهٖ مَسْرُوْرًاۗ", "Wa yanqalibu ilā ahlihī masrūrā(n).", "dan dia akan kembali kepada keluarganya (yang sama-sama beriman) dengan gembira."),
    Ayah(10, 84, "وَاَمَّا مَنْ اُوْتِيَ كِتٰبَهٗ وَرَاۤءَ ظَهْرِهٖۙ", "Wa ammā man ūtiya kitābahū warā'a ẓahrih(ī).", "Adapun orang yang catatannya diberikan dari belakang punggungnya,"),
    Ayah(11, 84, "فَسَوْفَ يَدْعُوْا ثُبُوْرًاۙ", "Fa saufa yad‘ū ṡubūrā(n).", "dia akan berteriak, “Celakalah aku!”"),
    Ayah(12, 84, "وَّيَصْلٰى سَعِيْرًاۗ", "Wa yaṣlā sa‘īrā(n).", "Dia akan memasuki (neraka) Sa‘ir (yang menyala-nyala)."),
    Ayah(13, 84, "اِنَّهٗ كَانَ فِيْٓ اَهْلِهٖ مَسْرُوْرًاۗ", "Innahū kāna fī ahlihī masrūrā(n).", "Sesungguhnya dia dahulu (di dunia) bergembira di kalangan keluarganya (yang sama-sama kafir)."),
    Ayah(14, 84, "اِنَّهٗ ظَنَّ اَنْ لَّنْ يَّحُوْرَ ۛ", "Innahū ẓanna allay yaḥūr(a).", "Sesungguhnya dia mengira bahwa dia tidak akan kembali (kepada Tuhannya)."),
    Ayah(15, 84, "بَلٰىۛ اِنَّ رَبَّهٗ كَانَ بِهٖ بَصِيْرًاۗ", "Balā, inna rabbahū kāna bihī baṣīrā(n).", "Tidak demikian. Sesungguhnya Tuhannya selalu melihatnya."),
    Ayah(16, 84, "فَلَآ اُقْسِمُ بِالشَّفَقِۙ", "Falā uqsimu bisy-syafaq(i).", "Aku bersumpah demi cahaya merah pada waktu senja,"),
    Ayah(17, 84, "وَالَّيْلِ وَمَا وَسَقَۙ", "Wal-laili wa mā wasaq(a).", "demi malam dan apa yang diselubunginya,"),
    Ayah(18, 84, "وَالْقَمَرِ اِذَا اتَّسَقَۙ", "Wal-qamari iżattasaq(a).", "dan demi bulan apabila jadi purnama,"),
    Ayah(19, 84, "لَتَرْكَبُنَّ طَبَقًا عَنْ طَبَقٍۗ", "Latarkabunna ṭabaqan ‘an ṭabaq(in).", "sungguh, kamu benar-benar akan menjalani tingkat demi tingkat (dalam kehidupan).752)"),
    Ayah(20, 84, "فَمَا لَهُمْ لَا يُؤْمِنُوْنَۙ", "Famā lahum lā yu'minūn(a).", "Maka, mengapa mereka tidak mau beriman?"),
    Ayah(21, 84, "وَاِذَا قُرِئَ عَلَيْهِمُ الْقُرْاٰنُ لَا يَسْجُدُوْنَ ۗ ۩", "Wa iżā quri'a ‘alaihimul-qur'ānu lā yasjudūn(a).", "Apabila Al-Qur’an dibacakan kepada mereka, mereka tidak (mau) bersujud,"),
    Ayah(22, 84, "بَلِ الَّذِيْنَ كَفَرُوْا يُكَذِّبُوْنَۖ", "Balil-lażīna kafarū yukażżibūn(a).", "bahkan orang-orang yang kufur itu mendustakan(-nya)."),
    Ayah(23, 84, "وَاللّٰهُ اَعْلَمُ بِمَا يُوْعُوْنَۖ", "Wallāhu a‘lamu bimā yū‘ūn(a).", "Allah lebih mengetahui apa yang mereka sembunyikan (dalam hati mereka)."),
    Ayah(24, 84, "فَبَشِّرْهُمْ بِعَذَابٍ اَلِيْمٍۙ", "Fa basysyirhum bi‘ażābin alīm(in).", "Maka, berilah mereka kabar ‘gembira’ dengan azab yang pedih,"),
    Ayah(25, 84, "اِلَّا الَّذِيْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِ لَهُمْ اَجْرٌ غَيْرُ مَمْنُوْنٍ ࣖ", "Illal-lażīna āmanū wa ‘amiluṣ-ṣāliḥāti lahum ajrun gairu mamnūn(in).", "Kecuali orang-orang yang beriman dan mengerjakan kebajikan. Bagi merekalah pahala yang tidak putus-putus."),
)

internal fun quranFullAyahs85(): List<Ayah> = listOf(
    Ayah(1, 85, "وَالسَّمَاۤءِ ذَاتِ الْبُرُوْجِۙ", "Was-samā'i żātil-burūj(i).", "Demi langit yang mempunyai gugusan bintang,"),
    Ayah(2, 85, "وَالْيَوْمِ الْمَوْعُوْدِۙ", "Wal-yaumil-mau‘ūd(i).", "demi hari yang dijanjikan,"),
    Ayah(3, 85, "وَشَاهِدٍ وَّمَشْهُوْدٍۗ", "Wa syāhidiw wa masyhūd(in).", "demi yang menyaksikan dan yang disaksikan,"),
    Ayah(4, 85, "قُتِلَ اَصْحٰبُ الْاُخْدُوْدِۙ", "Qutila aṣḥābul-ukhdūd(i).", "binasalah orang-orang yang membuat parit (tempat menyiksa orang mukmin)"),
    Ayah(5, 85, "النَّارِ ذَاتِ الْوَقُوْدِۙ", "An-nāri żātil-waqūd(i).", "(yang dikobarkan) api penuh kayu bakar."),
    Ayah(6, 85, "اِذْ هُمْ عَلَيْهَا قُعُوْدٌۙ", "Iż hum ‘alaihā qu‘ūd(un).", "Ketika (itu) mereka (hanya) duduk di sekitarnya."),
    Ayah(7, 85, "وَّهُمْ عَلٰى مَا يَفْعَلُوْنَ بِالْمُؤْمِنِيْنَ شُهُوْدٌ ۗ", "Wa hum ‘alā mā yaf‘alūna bil-mu'minīna syuhūd(un).", "Mereka menyaksikan apa yang mereka perbuat terhadap orang-orang mukmin."),
    Ayah(8, 85, "وَمَا نَقَمُوْا مِنْهُمْ اِلَّآ اَنْ يُّؤْمِنُوْا بِاللّٰهِ الْعَزِيْزِ الْحَمِيْدِۙ", "Wa mā naqamū minhum illā ay yu'minū billāhil-‘azīzil-ḥamīd(i).", "Tidaklah mereka menyiksa (membakar) orang-orang mukmin itu, kecuali karena mereka beriman kepada Allah Yang Mahaperkasa lagi Maha Terpuji,"),
    Ayah(9, 85, "الَّذِيْ لَهٗ مُلْكُ السَّمٰوٰتِ وَالْاَرْضِ ۗوَاللّٰهُ عَلٰى كُلِّ شَيْءٍ شَهِيْدٌ ۗ", "Allażī lahū mulkus-samāwāti wal-arḍ(i), wallāhu ‘alā kulli syai'in syahīd(un).", "yang memiliki kerajaan langit dan bumi. Allah Maha Menyaksikan segala sesuatu."),
    Ayah(10, 85, "اِنَّ الَّذِيْنَ فَتَنُوا الْمُؤْمِنِيْنَ وَالْمُؤْمِنٰتِ ثُمَّ لَمْ يَتُوْبُوْا فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ الْحَرِيْقِۗ", "Innal-lażīna fatanul-mu'minīna wal-mu'mināti ṡumma lam yatūbū fa lahum ‘ażābu jahannama wa lahum ‘ażābul-ḥarīq(i).", "Sesungguhnya, orang-orang yang menimpakan cobaan (siksa) terhadap mukmin laki-laki dan perempuan, lalu mereka tidak bertobat, mereka akan mendapat azab Jahanam dan mereka akan mendapat azab (neraka) yang membakar."),
    Ayah(11, 85, "اِنَّ الَّذِيْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِ لَهُمْ جَنّٰتٌ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ ەۗ ذٰلِكَ الْفَوْزُ الْكَبِيْرُۗ", "Innal-lażīna āmanū wa ‘amiluṣ-ṣāliḥāti lahum jannātun tajrī min taḥtihal-anhār(u), żālikal-fauzul-kabīr(u).", "Sesungguhnya, orang-orang yang beriman dan mengerjakan kebajikan, mereka akan mendapat surga yang mengalir di bawahnya sungai-sungai. Itulah kemenangan yang besar."),
    Ayah(12, 85, "اِنَّ بَطْشَ رَبِّكَ لَشَدِيْدٌ ۗ", "Inna baṭsya rabbika lasyadīd(un).", "Sesungguhnya azab Tuhanmu sangat keras."),
    Ayah(13, 85, "اِنَّهٗ هُوَ يُبْدِئُ وَيُعِيْدُۚ", "Innahū huwa yubdi'u wa yu‘īd(u).", "Sesungguhnya Dialah yang memulai (penciptaan makhluk) dan yang mengembalikan (hidup setelah mati)."),
    Ayah(14, 85, "وَهُوَ الْغَفُوْرُ الْوَدُوْدُۙ", "Wa huwal-gafūrul-wadūd(u).", "Dialah Yang Maha Pengampun lagi Maha Pengasih,"),
    Ayah(15, 85, "ذُو الْعَرْشِ الْمَجِيْدُۙ", "Żul-‘arsyil-majīd(i).", "Pemilik ʻArasy lagi Mahamulia,"),
    Ayah(16, 85, "فَعَّالٌ لِّمَا يُرِيْدُۗ", "Fa‘‘ālul limā yurīd(u).", "Mahakuasa berbuat apa saja yang Dia kehendaki."),
    Ayah(17, 85, "هَلْ اَتٰىكَ حَدِيْثُ الْجُنُوْدِۙ", "Hal atāka ḥadīṡul-junūd(i).", "Sudahkah sampai kepadamu berita tentang bala tentara,"),
    Ayah(18, 85, "فِرْعَوْنَ وَثَمُوْدَۗ", "Fir‘auna wa ṡamūd(a).", "(yaitu bala tentara) Fir‘aun dan Samud?"),
    Ayah(19, 85, "بَلِ الَّذِيْنَ كَفَرُوْا فِيْ تَكْذِيْبٍۙ", "Balil-lażīna kafarū fī takżīb(in).", "Memang orang-orang kafir (selalu) mendustakan,"),
    Ayah(20, 85, "وَّاللّٰهُ مِنْ وَّرَاۤىِٕهِمْ مُّحِيْطٌۚ", "Wallāhu miw warā'ihim muḥīṭ(un).", "padahal Allah mengepung dari belakang mereka."),
    Ayah(21, 85, "بَلْ هُوَ قُرْاٰنٌ مَّجِيْدٌۙ", "Bal huwa qur'ānum majīd(un).", "Bahkan, (yang didustakan itu) Al-Qur’an yang mulia"),
    Ayah(22, 85, "فِيْ لَوْحٍ مَّحْفُوْظٍ ࣖ", "Fī lauḥim maḥfūẓ(in).", "yang (tersimpan) dalam (tempat) yang terjaga (Lauh Mahfuz)."),
)

internal fun quranFullAyahs86(): List<Ayah> = listOf(
    Ayah(1, 86, "وَالسَّمَاۤءِ وَالطَّارِقِۙ", "Was-samā'i waṭ-ṭāriq(i).", "Demi langit dan yang datang pada malam hari."),
    Ayah(2, 86, "وَمَآ اَدْرٰىكَ مَا الطَّارِقُۙ", "Wa mā adrāka maṭ-ṭāriq(u).", "Tahukah kamu apakah yang datang pada malam hari itu?"),
    Ayah(3, 86, "النَّجْمُ الثَّاقِبُۙ", "An-najmuṡ-ṡāqib(u).", "(Itulah) bintang yang bersinar tajam."),
    Ayah(4, 86, "اِنْ كُلُّ نَفْسٍ لَّمَّا عَلَيْهَا حَافِظٌۗ", "In kullu nafsil lammā ‘alaihā ḥāfiẓ(un).", "Setiap orang pasti ada penjaganya."),
    Ayah(5, 86, "فَلْيَنْظُرِ الْاِنْسَانُ مِمَّ خُلِقَ", "Falyanẓuril-insānu mimma khuliq(a).", "Hendaklah manusia memperhatikan dari apa dia diciptakan."),
    Ayah(6, 86, "خُلِقَ مِنْ مَّاۤءٍ دَافِقٍۙ", "Khuliqa mim mā'in dāfiq(in).", "Dia diciptakan dari air (mani) yang memancar,"),
    Ayah(7, 86, "يَّخْرُجُ مِنْۢ بَيْنِ الصُّلْبِ وَالتَّرَاۤىِٕبِۗ", "Yakhruju mim bainiṣ-ṣulbi wat-tarā'ib(i).", "yang keluar dari antara tulang sulbi (punggung) dan tulang dada."),
    Ayah(8, 86, "اِنَّهٗ عَلٰى رَجْعِهٖ لَقَادِرٌۗ", "Innahū ‘alā raj‘ihī laqādir(un).", "Sesungguhnya Dia (Allah) benar-benar kuasa untuk mengembalikannya (hidup setelah mati)"),
    Ayah(9, 86, "يَوْمَ تُبْلَى السَّرَاۤىِٕرُۙ", "Yauma tublas-sarā'ir(u).", "pada hari ditampakkan segala rahasia."),
    Ayah(10, 86, "فَمَا لَهٗ مِنْ قُوَّةٍ وَّلَا نَاصِرٍۗ", "Famā lahū min quwwatiw wa lā nāṣir(in).", "Maka, baginya (manusia) tidak ada lagi kekuatan dan tidak (pula) ada penolong."),
    Ayah(11, 86, "وَالسَّمَاۤءِ ذَاتِ الرَّجْعِۙ", "Was-samā'i żātir-raj‘(i).", "Demi langit yang mengandung hujan753)"),
    Ayah(12, 86, "وَالْاَرْضِ ذَاتِ الصَّدْعِۙ", "Wal-arḍi żātiṣ-ṣad‘(i).", "dan bumi yang memiliki rekahan (tempat tumbuhnya pepohonan),"),
    Ayah(13, 86, "اِنَّهٗ لَقَوْلٌ فَصْلٌۙ", "Innahū laqaulun faṣl(un).", "sesungguhnya (Al-Qur’an) itu benar-benar firman pemisah (antara yang hak dan yang batil)"),
    Ayah(14, 86, "وَّمَا هُوَ بِالْهَزْلِۗ", "Wa mā huwa bil-hazl(i).", "dan ia (Al-Qur’an) sama sekali bukan perkataan senda gurau."),
    Ayah(15, 86, "اِنَّهُمْ يَكِيْدُوْنَ كَيْدًاۙ", "Innahum yakīdūna kaidā(n).", "Sesungguhnya mereka (orang kafir) melakukan tipu daya."),
    Ayah(16, 86, "وَّاَكِيْدُ كَيْدًاۖ", "Wa akīdu kaidā(n).", "Aku pun membalasnya dengan tipu daya."),
    Ayah(17, 86, "فَمَهِّلِ الْكٰفِرِيْنَ اَمْهِلْهُمْ رُوَيْدًا ࣖ", "Fa mahhilil-kāfirīna amhilhum ruwaidā(n).", "Maka, tangguhkanlah orang-orang kafir itu. Biarkanlah mereka sejenak (bersenang-senang)."),
)

internal fun quranFullAyahs87(): List<Ayah> = listOf(
    Ayah(1, 87, "سَبِّحِ اسْمَ رَبِّكَ الْاَعْلَىۙ", "Sabbiḥisma rabbikal-a‘lā.", "Sucikanlah nama Tuhanmu Yang Mahatinggi,"),
    Ayah(2, 87, "الَّذِيْ خَلَقَ فَسَوّٰىۖ", "Allażī khalaqa fasawwā.", "yang menciptakan, lalu menyempurnakan (ciptaan-Nya),"),
    Ayah(3, 87, "وَالَّذِيْ قَدَّرَ فَهَدٰىۖ", "Wal-lażī qaddara fahadā.", "yang menentukan kadar (masing-masing) dan memberi petunjuk,"),
    Ayah(4, 87, "وَالَّذِيْٓ اَخْرَجَ الْمَرْعٰىۖ", "Wal-lażī akhrajal-mar‘ā.", "dan yang menumbuhkan (rerumputan) padang gembala,"),
    Ayah(5, 87, "فَجَعَلَهٗ غُثَاۤءً اَحْوٰىۖ", "Fa ja‘alahū guṡā'an aḥwā.", "lalu menjadikannya kering kehitam-hitaman."),
    Ayah(6, 87, "سَنُقْرِئُكَ فَلَا تَنْسٰىٓ ۖ", "Sanuqri'uka falā tansā.", "Kami akan membacakan (Al-Qur’an) kepadamu (Nabi Muhammad) sehingga engkau tidak akan lupa,"),
    Ayah(7, 87, "اِلَّا مَا شَاۤءَ اللّٰهُ ۗاِنَّهٗ يَعْلَمُ الْجَهْرَ وَمَا يَخْفٰىۗ", "Illā mā syā'allāh(u), innahū ya‘lamul-jahra wa mā yakhfā.", "kecuali jika Allah menghendaki. Sesungguhnya Dia mengetahui yang terang dan yang tersembunyi."),
    Ayah(8, 87, "وَنُيَسِّرُكَ لِلْيُسْرٰىۖ", "Wa nuyassiruka lil-yusrā.", "Kami akan melapangkan bagimu jalan kemudahan (dalam segala urusan)."),
    Ayah(9, 87, "فَذَكِّرْ اِنْ نَّفَعَتِ الذِّكْرٰىۗ", "Fa żakkir in nafa‘atiż-żikrā.", "Maka, sampaikanlah peringatan jika peringatan itu bermanfaat."),
    Ayah(10, 87, "سَيَذَّكَّرُ مَنْ يَّخْشٰىۙ", "Sayażżakkaru may yakhsyā.", "Orang yang takut (kepada Allah) akan mengambil pelajaran,"),
    Ayah(11, 87, "وَيَتَجَنَّبُهَا الْاَشْقَىۙ", "Wa yatajannabuhal-asyqā.", "sedangkan orang-orang yang celaka (kafir) akan menjauhinya,"),
    Ayah(12, 87, "الَّذِيْ يَصْلَى النَّارَ الْكُبْرٰىۚ", "Allażī yaṣlan-nāral-kubrā.", "(yaitu) orang yang akan memasuki api (neraka) yang besar."),
    Ayah(13, 87, "ثُمَّ لَا يَمُوْتُ فِيْهَا وَلَا يَحْيٰىۗ", "Ṡumma lā yamūtu fīhā wa lā yaḥyā.", "Selanjutnya, dia tidak mati dan tidak (pula) hidup di sana."),
    Ayah(14, 87, "قَدْ اَفْلَحَ مَنْ تَزَكّٰىۙ", "Qad aflaḥa man tazakkā.", "Sungguh, beruntung orang yang menyucikan diri (dari kekafiran)"),
    Ayah(15, 87, "وَذَكَرَ اسْمَ رَبِّهٖ فَصَلّٰىۗ", "Wa żakarasma rabbihī fa ṣallā.", "dan mengingat nama Tuhannya, lalu dia salat."),
    Ayah(16, 87, "بَلْ تُؤْثِرُوْنَ الْحَيٰوةَ الدُّنْيَاۖ", "Bal tu'ṡirūnal-ḥayātad-dun-yā.", "Adapun kamu (orang-orang kafir) mengutamakan kehidupan dunia,"),
    Ayah(17, 87, "وَالْاٰخِرَةُ خَيْرٌ وَّاَبْقٰىۗ", "Wal-ākhiratu khairuw wa abqā.", "padahal kehidupan akhirat itu lebih baik dan lebih kekal."),
    Ayah(18, 87, "اِنَّ هٰذَا لَفِى الصُّحُفِ الْاُوْلٰىۙ", "Inna hāżā lafiṣ-ṣuḥufil-ūlā.", "Sesungguhnya (penjelasan) ini terdapat dalam suhuf (lembaran-lembaran) yang terdahulu,"),
    Ayah(19, 87, "صُحُفِ اِبْرٰهِيْمَ وَمُوْسٰى ࣖ", "Ṣuḥufi ibrāhīma wa mūsā.", "(yaitu) suhuf (yang diturunkan kepada) Ibrahim dan Musa."),
)

internal fun quranFullAyahs88(): List<Ayah> = listOf(
    Ayah(1, 88, "هَلْ اَتٰىكَ حَدِيْثُ الْغَاشِيَةِۗ", "Hal atāka ḥadīṡul-gāsyiyah(ti).", "Sudahkah sampai kepadamu berita tentang al-Gāsyiyah (hari Kiamat yang menutupi kesadaran manusia dengan kedahsyatannya)?"),
    Ayah(2, 88, "وُجُوْهٌ يَّوْمَىِٕذٍ خَاشِعَةٌ ۙ", "Wujūhuy yauma'iżin khāsyi‘ah(tun).", "Pada hari itu banyak wajah yang tertunduk hina"),
    Ayah(3, 88, "عَامِلَةٌ نَّاصِبَةٌ ۙ", "‘Amilatun nāṣibah(tun).", "(karena) berusaha keras (menghindari azab neraka) lagi kepayahan (karena dibelenggu)."),
    Ayah(4, 88, "تَصْلٰى نَارًا حَامِيَةً ۙ", "Taṣlā nāran ḥāmiyah(tan).", "Mereka memasuki api (neraka) yang sangat panas."),
    Ayah(5, 88, "تُسْقٰى مِنْ عَيْنٍ اٰنِيَةٍ ۗ", "Tusqā min ‘ainin āniyah(tin).", "(Mereka) diberi minum dari sumber mata air yang sangat panas."),
    Ayah(6, 88, "لَيْسَ لَهُمْ طَعَامٌ اِلَّا مِنْ ضَرِيْعٍۙ", "Laisa lahum ṭa‘āmun illā min ḍarī‘(in).", "Tidak ada makanan bagi mereka selain dari pohon yang berduri,"),
    Ayah(7, 88, "لَّا يُسْمِنُ وَلَا يُغْنِيْ مِنْ جُوْعٍۗ", "Lā yusminu wa lā yugnī min jū‘(in).", "yang tidak menggemukkan dan tidak pula menghilangkan lapar."),
    Ayah(8, 88, "وُجُوْهٌ يَّوْمَىِٕذٍ نَّاعِمَةٌ ۙ", "Wujūhuy yauma'iżin nā‘imah(tun).", "Pada hari itu banyak (pula) wajah yang berseri-seri,"),
    Ayah(9, 88, "لِّسَعْيِهَا رَاضِيَةٌ ۙ", "Lisa‘yihā rāḍiyah(tun).", "merasa puas karena usahanya."),
    Ayah(10, 88, "فِيْ جَنَّةٍ عَالِيَةٍۙ", "Fī jannatin ‘āliyah(tin).", "(Mereka) dalam surga yang tinggi."),
    Ayah(11, 88, "لَّا تَسْمَعُ فِيْهَا لَاغِيَةً ۗ", "Lā tasama‘u fīhā lāgiyah(tan).", "Di sana kamu tidak mendengar (perkataan) yang tidak berguna."),
    Ayah(12, 88, "فِيْهَا عَيْنٌ جَارِيَةٌ ۘ", "Fīhā ‘ainun jāriyah(tun).", "Di sana ada mata air yang mengalir."),
    Ayah(13, 88, "فِيْهَا سُرُرٌ مَّرْفُوْعَةٌ ۙ", "Fīhā sururum marfū‘ah(tun).", "Di sana ada (pula) dipan-dipan yang ditinggikan,"),
    Ayah(14, 88, "وَّاَكْوَابٌ مَّوْضُوْعَةٌ ۙ", "Wa akwābum mauḍū‘ah(tun).", "gelas-gelas yang tersedia (di dekatnya),"),
    Ayah(15, 88, "وَّنَمَارِقُ مَصْفُوْفَةٌ ۙ", "Wa namāriqu maṣfūfah(tun).", "bantal-bantal sandaran yang tersusun,"),
    Ayah(16, 88, "وَّزَرَابِيُّ مَبْثُوْثَةٌ ۗ", "Wa zarābiyyu mabṡūṡah(tun).", "dan permadani-permadani yang terhampar."),
    Ayah(17, 88, "اَفَلَا يَنْظُرُوْنَ اِلَى الْاِبِلِ كَيْفَ خُلِقَتْۗ", "Afalā yanẓurūna ilal-ibili kaifa khuliqat.", "Tidakkah mereka memperhatikan unta, bagaimana ia diciptakan?"),
    Ayah(18, 88, "وَاِلَى السَّمَاۤءِ كَيْفَ رُفِعَتْۗ", "Wa ilas-samā'i kaifa rufi‘at.", "Bagaimana langit ditinggikan?"),
    Ayah(19, 88, "وَاِلَى الْجِبَالِ كَيْفَ نُصِبَتْۗ", "Wa ilal-jibāli kaifa nuṣibat.", "Bagaimana gunung-gunung ditegakkan?"),
    Ayah(20, 88, "وَاِلَى الْاَرْضِ كَيْفَ سُطِحَتْۗ", "Wa ilal-arḍi kaifa suṭiḥat.", "Bagaimana pula bumi dihamparkan?"),
    Ayah(21, 88, "فَذَكِّرْۗ اِنَّمَآ اَنْتَ مُذَكِّرٌۙ", "Fa żakkir, innamā anta mużakkir(un).", "Maka, berilah peringatan karena sesungguhnya engkau (Nabi Muhammad) hanyalah pemberi peringatan."),
    Ayah(22, 88, "لَّسْتَ عَلَيْهِمْ بِمُصَيْطِرٍۙ", "Lasta ‘alaihim bimusaiṭir(in).", "Engkau bukanlah orang yang berkuasa atas mereka."),
    Ayah(23, 88, "اِلَّا مَنْ تَوَلّٰى وَكَفَرَۙ", "Illā man tawallā wa kafar(a).", "Akan tetapi, orang yang berpaling dan kufur,"),
    Ayah(24, 88, "فَيُعَذِّبُهُ اللّٰهُ الْعَذَابَ الْاَكْبَرَۗ", "Fa yu‘ażżibuhullāhul-‘ażābal-akbar(a).", "Allah akan mengazabnya dengan azab yang paling besar."),
    Ayah(25, 88, "اِنَّ اِلَيْنَآ اِيَابَهُمْ", "Inna ilainā iyābahum.", "Sesungguhnya kepada Kamilah mereka kembali."),
    Ayah(26, 88, "ثُمَّ اِنَّ عَلَيْنَا حِسَابَهُمْ ࣖ", "Ṡumma inna ‘alainā ḥisābahum.", "Kemudian, sesungguhnya Kamilah yang berhak melakukan hisab (perhitungan) atas mereka."),
)

internal fun quranFullAyahs89(): List<Ayah> = listOf(
    Ayah(1, 89, "وَالْفَجْرِۙ", "Wal-fajr(i).", "Demi waktu fajar,"),
    Ayah(2, 89, "وَلَيَالٍ عَشْرٍۙ", "Wa layālin ‘asyr(in).", "demi malam yang sepuluh,754)"),
    Ayah(3, 89, "وَّالشَّفْعِ وَالْوَتْرِۙ", "Wasy-syaf‘i wal-watr(i).", "demi yang genap dan yang ganjil,"),
    Ayah(4, 89, "وَالَّيْلِ اِذَا يَسْرِۚ", "Wal-laili iżā yasr(i).", "dan demi malam apabila berlalu."),
    Ayah(5, 89, "هَلْ فِيْ ذٰلِكَ قَسَمٌ لِّذِيْ حِجْرٍۗ", "Hal fī żālika qasamul liżī ḥijr(in).", "Apakah pada yang demikian itu terdapat sumpah (yang dapat diterima) oleh (orang) yang berakal?"),
    Ayah(6, 89, "اَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍۖ", "Alam tara kaifa fa‘ala rabbuka bi‘ād(in).", "Tidakkah engkau (Nabi Muhammad) memperhatikan bagaimana Tuhanmu berbuat terhadap (kaum) ‘Ad,"),
    Ayah(7, 89, "اِرَمَ ذَاتِ الْعِمَادِۖ", "Irama żātil-‘imād(i).", "(yaitu) penduduk Iram (ibu kota kaum ‘Ad) yang mempunyai bangunan-bangunan yang tinggi"),
    Ayah(8, 89, "الَّتِيْ لَمْ يُخْلَقْ مِثْلُهَا فِى الْبِلَادِۖ", "Allatī lam yukhlaq miṡluhā fil-bilād(i).", "yang sebelumnya tidak pernah dibangun (suatu kota pun) seperti itu di negeri-negeri (lain)?"),
    Ayah(9, 89, "وَثَمُوْدَ الَّذِيْنَ جَابُوا الصَّخْرَ بِالْوَادِۖ", "Wa ṡamūdal-lażīna jābuṣ-ṣakhra bil-wād(i).", "(Tidakkah engkau perhatikan pula kaum) Samud yang memotong batu-batu besar di lembah755)"),
    Ayah(10, 89, "وَفِرْعَوْنَ ذِى الْاَوْتَادِۖ", "Wa fir‘auna żil-autād(i).", "dan Fir‘aun yang mempunyai pasak-pasak (bangunan yang besar)"),
    Ayah(11, 89, "الَّذِيْنَ طَغَوْا فِى الْبِلَادِۖ", "Allażīna ṭagau fil-bilād(i).", "yang berbuat sewenang-wenang dalam negeri,"),
    Ayah(12, 89, "فَاَكْثَرُوْا فِيْهَا الْفَسَادَۖ", "Fa akṡarū fīhal-fasād(a).", "lalu banyak berbuat kerusakan di dalamnya (negeri itu),"),
    Ayah(13, 89, "فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍۖ", "Fa ṣabba ‘alaihim rabbuka sauṭa ‘ażāb(in).", "maka Tuhanmu menimpakan cemeti azab (yang dahsyat) kepada mereka?"),
    Ayah(14, 89, "اِنَّ رَبَّكَ لَبِالْمِرْصَادِۗ", "Inna rabbaka labil-mirṣād(i).", "Sesungguhnya Tuhanmu benar-benar mengawasi."),
    Ayah(15, 89, "فَاَمَّا الْاِنْسَانُ اِذَا مَا ابْتَلٰىهُ رَبُّهٗ فَاَكْرَمَهٗ وَنَعَّمَهٗۙ فَيَقُوْلُ رَبِّيْٓ اَكْرَمَنِۗ", "Fa ammal-insānu iżā mabtalāhu rabbuhū fa akramahū wa na‘‘amah(ū), fa yaqūlu rabbī akraman(i).", "Adapun manusia, apabila Tuhan mengujinya lalu memuliakannya dan memberinya kenikmatan, berkatalah dia, “Tuhanku telah memuliakanku.”"),
    Ayah(16, 89, "وَاَمَّآ اِذَا مَا ابْتَلٰىهُ فَقَدَرَ عَلَيْهِ رِزْقَهٗ ەۙ فَيَقُوْلُ رَبِّيْٓ اَهَانَنِۚ", "Wa ammā iżā mabtalāhu fa qadara ‘alaihi rizqah(ū), fa yaqūlu rabbī ahānan(i).", "Sementara itu, apabila Dia mengujinya lalu membatasi rezekinya, berkatalah dia, “Tuhanku telah menghinaku.”756)"),
    Ayah(17, 89, "كَلَّا بَلْ لَّا تُكْرِمُوْنَ الْيَتِيْمَۙ", "Kallā bal lā tukrimūnal-yatīm(a).", "Sekali-kali tidak! Sebaliknya, kamu tidak memuliakan anak yatim,757)"),
    Ayah(18, 89, "وَلَا تَحٰۤضُّوْنَ عَلٰى طَعَامِ الْمِسْكِيْنِۙ", "Wa lā taḥāḍḍūna ‘alā ṭa‘āmil-miskīn(i).", "tidak saling mengajak memberi makan orang miskin,"),
    Ayah(19, 89, "وَتَأْكُلُوْنَ التُّرَاثَ اَكْلًا لَّمًّاۙ", "Wa ta'kulūnat-turāṡa aklal lammā(n).", "memakan harta warisan dengan cara mencampurbaurkan (yang halal dan yang haram),"),
    Ayah(20, 89, "وَّتُحِبُّوْنَ الْمَالَ حُبًّا جَمًّاۗ", "Wa tuḥibbūnal-māla ḥubban jammā(n).", "dan mencintai harta dengan kecintaan yang berlebihan."),
    Ayah(21, 89, "كَلَّآ اِذَا دُكَّتِ الْاَرْضُ دَكًّا دَكًّاۙ", "Kallā iżā dukkatil-arḍu dakkan dakkā(n).", "Jangan sekali-kali begitu! Apabila bumi diguncangkan berturut-turut (berbenturan),"),
    Ayah(22, 89, "وَّجَاۤءَ رَبُّكَ وَالْمَلَكُ صَفًّا صَفًّاۚ", "Wa jā'a rabbuka wal-malaku ṣaffan ṣaffā(n).", "Tuhanmu datang, begitu pula para malaikat (yang datang) berbaris-baris,"),
    Ayah(23, 89, "وَجِايْۤءَ يَوْمَىِٕذٍۢ بِجَهَنَّمَۙ يَوْمَىِٕذٍ يَّتَذَكَّرُ الْاِنْسَانُ وَاَنّٰى لَهُ الذِّكْرٰىۗ", "Wa jī'a yauma'iżim bijahannam(a), yauma'iżiy yatażakkarul-insānu wa annā lahuż-żikrā.", "dan pada hari itu (neraka) Jahanam didatangkan, sadarlah manusia pada hari itu juga. Akan tetapi, bagaimana bisa kesadaran itu bermanfaat baginya?"),
    Ayah(24, 89, "يَقُوْلُ يٰلَيْتَنِيْ قَدَّمْتُ لِحَيَاتِيْۚ", "Yaqūlu yā laitanī qaddamtu liḥayātī.", "Dia berkata, “Oh, seandainya dahulu aku mengerjakan (kebajikan) untuk hidupku ini!”"),
    Ayah(25, 89, "فَيَوْمَىِٕذٍ لَّا يُعَذِّبُ عَذَابَهٗٓ اَحَدٌ ۙ", "Fa yauma'iżil lā yu‘ażżibu ‘ażābahū aḥad(un).", "Pada hari itu tidak ada seorang pun yang mampu mengazab (seadil) azab-Nya."),
    Ayah(26, 89, "وَّلَا يُوْثِقُ وَثَاقَهٗٓ اَحَدٌ ۗ", "Wa lā yūṡiqu waṡāqahū aḥad(un).", "Tidak ada seorang pun juga yang mampu mengikat (sekuat) ikatan-Nya."),
    Ayah(27, 89, "يٰٓاَيَّتُهَا النَّفْسُ الْمُطْمَىِٕنَّةُۙ", "Yā ayyatuhan-nafsul-muṭma'innah(tu).", "Wahai jiwa yang tenang,"),
    Ayah(28, 89, "ارْجِعِيْٓ اِلٰى رَبِّكِ رَاضِيَةً مَّرْضِيَّةً ۚ", "Irji‘ī ilā rabbiki rāḍiyatam marḍiyyah(tan).", "kembalilah kepada Tuhanmu dengan rida dan diridai."),
    Ayah(29, 89, "فَادْخُلِيْ فِيْ عِبٰدِيْۙ", "Fadkhuli fī ‘ibādī.", "Lalu, masuklah ke dalam golongan hamba-hamba-Ku"),
    Ayah(30, 89, "وَادْخُلِيْ جَنَّتِيْ ࣖࣖ", "Wadkhulī jannatī.", "dan masuklah ke dalam surga-Ku!"),
)

internal fun quranFullAyahs90(): List<Ayah> = listOf(
    Ayah(1, 90, "لَآ اُقْسِمُ بِهٰذَا الْبَلَدِۙ", "Lā uqsimu bihāżal-balad(i).", "Aku bersumpah demi negeri ini (Makkah),"),
    Ayah(2, 90, "وَاَنْتَ حِلٌّۢ بِهٰذَا الْبَلَدِۙ", "Wa anta ḥillum bihāżal-balad(i).", "sedangkan engkau (Nabi Muhammad) bertempat tinggal di negeri (Makkah) ini."),
    Ayah(3, 90, "وَوَالِدٍ وَّمَا وَلَدَۙ", "Wa wālidiw wa mā walad(a).", "(Aku juga bersumpah) demi bapak dan anaknya,"),
    Ayah(4, 90, "لَقَدْ خَلَقْنَا الْاِنْسَانَ فِيْ كَبَدٍۗ", "Laqad khalaqnal-insāna fī kabad(in).", "sungguh, Kami benar-benar telah menciptakan manusia dalam keadaan susah payah."),
    Ayah(5, 90, "اَيَحْسَبُ اَنْ لَّنْ يَّقْدِرَ عَلَيْهِ اَحَدٌ ۘ", "Ayaḥsabu allay yaqdira ‘alaihi aḥad(un).", "Apakah dia (manusia) itu mengira bahwa tidak ada seorang pun yang berkuasa atasnya?"),
    Ayah(6, 90, "يَقُوْلُ اَهْلَكْتُ مَالًا لُّبَدًاۗ", "Yaqūlu ahlaktu mālal lubadā(n).", "Dia mengatakan, “Aku telah menghabiskan harta yang banyak.”"),
    Ayah(7, 90, "اَيَحْسَبُ اَنْ لَّمْ يَرَهٗٓ اَحَدٌۗ", "Ayaḥsabu allam yarahū aḥad(un).", "Apakah dia mengira bahwa tidak ada seorang pun yang melihatnya?"),
    Ayah(8, 90, "اَلَمْ نَجْعَلْ لَّهٗ عَيْنَيْنِۙ", "Alam naj‘al lahū ‘ainain(i).", "Bukankah Kami telah menjadikan untuknya sepasang mata,"),
    Ayah(9, 90, "وَلِسَانًا وَّشَفَتَيْنِۙ", "Wa lisānaw wa syafatain(i).", "lidah, dan sepasang bibir,"),
    Ayah(10, 90, "وَهَدَيْنٰهُ النَّجْدَيْنِۙ", "Wa hadaināhun-najdain(i).", "serta Kami juga telahmenunjukkan kepadanya dua jalan (kebajikan dan kejahatan)?"),
    Ayah(11, 90, "فَلَا اقْتَحَمَ الْعَقَبَةَ ۖ", "Falaqtaḥamal-‘aqabah(ta).", "Maka, tidakkah sebaiknya dia menempuh jalan (kebajikan) yang mendaki dan sukar?"),
    Ayah(12, 90, "وَمَآ اَدْرٰىكَ مَا الْعَقَبَةُ ۗ", "Wa mā adrāka mal-‘aqabah(tu).", "Tahukah kamu apakah jalan yang mendaki dan sukar itu?"),
    Ayah(13, 90, "فَكُّ رَقَبَةٍۙ", "Fakku raqabah(tin).", "(Itulah upaya) melepaskan perbudakan"),
    Ayah(14, 90, "اَوْ اِطْعَامٌ فِيْ يَوْمٍ ذِيْ مَسْغَبَةٍۙ", "Au iṭ‘āmun fī yaumin żī masgabah(tin).", "atau memberi makan pada hari terjadi kelaparan"),
    Ayah(15, 90, "يَّتِيْمًا ذَا مَقْرَبَةٍۙ", "Yatīman żā maqrabah(tin).", "(kepada) anak yatim yang memiliki hubungan kekerabatan"),
    Ayah(16, 90, "اَوْ مِسْكِيْنًا ذَا مَتْرَبَةٍۗ", "Au miskīnan żā matrabah(tin).", "atau orang miskin yang sangat membutuhkan."),
    Ayah(17, 90, "ثُمَّ كَانَ مِنَ الَّذِيْنَ اٰمَنُوْا وَتَوَاصَوْا بِالصَّبْرِ وَتَوَاصَوْا بِالْمَرْحَمَةِۗ", "Ṡumma kāna minal-lażīna āmanū wa tawāṣau biṣ-ṣabri wa tawāṣau bil-marḥamah(ti).", "Kemudian, dia juga termasuk orang-orang yang beriman dan saling berpesan untuk bersabar serta saling berpesan untuk berkasih sayang."),
    Ayah(18, 90, "اُولٰۤىِٕكَ اَصْحٰبُ الْمَيْمَنَةِۗ", "Ulā'ika aṣḥābul-maimanah(ti).", "Mereka itulah golongan kanan."),
    Ayah(19, 90, "وَالَّذِيْنَ كَفَرُوْا بِاٰيٰتِنَا هُمْ اَصْحٰبُ الْمَشْـَٔمَةِۗ", "Wal-lażīna kafarū bi'āyātinā hum aṣḥābul-masy'amah(ti).", "Adapun orang-orang yang kufur pada ayat-ayat Kami, merekalah golongan kiri."),
    Ayah(20, 90, "عَلَيْهِمْ نَارٌ مُّؤْصَدَةٌ ࣖ", "‘Alaihim nārum mu'ṣadah(tun).", "Mereka berada dalam neraka yang ditutup rapat."),
)

internal fun quranFullAyahs91(): List<Ayah> = listOf(
    Ayah(1, 91, "وَالشَّمْسِ وَضُحٰىهَاۖ", "Wasy-syamsi wa ḍuḥāhā.", "Demi matahari dan sinarnya pada waktu duha (ketika matahari naik sepenggalah),"),
    Ayah(2, 91, "وَالْقَمَرِ اِذَا تَلٰىهَاۖ", "Wal-qamari iżā talāhā.", "demi bulan saat mengiringinya,"),
    Ayah(3, 91, "وَالنَّهَارِ اِذَا جَلّٰىهَاۖ", "Wan-nahāri iżā jallāhā.", "demi siang saat menampakkannya,"),
    Ayah(4, 91, "وَالَّيْلِ اِذَا يَغْشٰىهَاۖ", "Wal-laili iżā yagsyāhā.", "demi malam saat menutupinya (gelap gulita),"),
    Ayah(5, 91, "وَالسَّمَاۤءِ وَمَا بَنٰىهَاۖ", "Was-samā'i wa mā banāhā.", "demi langit serta pembuatannya,"),
    Ayah(6, 91, "وَالْاَرْضِ وَمَا طَحٰىهَاۖ", "Wal-arḍi wa mā ṭaḥāhā.", "demi bumi serta penghamparannya,"),
    Ayah(7, 91, "وَنَفْسٍ وَّمَا سَوّٰىهَاۖ", "Wa nafsiw wa mā sawwāhā.", "dan demi jiwa serta penyempurnaan (ciptaan)-nya,"),
    Ayah(8, 91, "فَاَلْهَمَهَا فُجُوْرَهَا وَتَقْوٰىهَاۖ", "Fa alhamahā fujūrahā wa taqwāhā.", "lalu Dia mengilhamkan kepadanya (jalan) kejahatan dan ketakwaannya,"),
    Ayah(9, 91, "قَدْ اَفْلَحَ مَنْ زَكّٰىهَاۖ", "Qad aflaḥa man zakkāhā.", "sungguh beruntung orang yang menyucikannya (jiwa itu)"),
    Ayah(10, 91, "وَقَدْ خَابَ مَنْ دَسّٰىهَاۗ", "Wa qad khāba man dassāhā.", "dan sungguh rugi orang yang mengotorinya."),
    Ayah(11, 91, "كَذَّبَتْ ثَمُوْدُ بِطَغْوٰىهَآ ۖ", "Każżabat ṡamūdu biṭagwāhā.", "(Kaum) Samud telah mendustakan (rasulnya) karena mereka melampaui batas"),
    Ayah(12, 91, "اِذِ انْۢبَعَثَ اَشْقٰىهَاۖ", "Iżimba‘aṡa asyqāhā.", "ketika orang yang paling celaka di antara mereka bangkit (untuk menyembelih unta betina Allah)."),
    Ayah(13, 91, "فَقَالَ لَهُمْ رَسُوْلُ اللّٰهِ نَاقَةَ اللّٰهِ وَسُقْيٰهَاۗ", "Fa qāla lahum rasūlullāhi nāqatallāhi wa suqyāhā.", "Rasul Allah (Saleh) lalu berkata kepada mereka, “(Biarkanlah) unta betina Allah ini beserta minumannya.”"),
    Ayah(14, 91, "فَكَذَّبُوْهُ فَعَقَرُوْهَاۖ فَدَمْدَمَ عَلَيْهِمْ رَبُّهُمْ بِذَنْۢبِهِمْ فَسَوّٰىهَاۖ", "Fa każżabūhu fa ‘aqarūhā fa damdama ‘alaihim rabbuhum biżambihim fa sawwāhā.", "Namun, mereka kemudian mendustakannya (Saleh) dan menyembelih (unta betina) itu. Maka, Tuhan membinasakan mereka karena dosa-dosanya, lalu meratakan mereka (dengan tanah)."),
    Ayah(15, 91, "وَلَا يَخَافُ عُقْبٰهَا ࣖ", "Wa lā yakhāfu ‘uqbāhā.", "Dia tidak takut terhadap akibatnya."),
)

internal fun quranFullAyahs92(): List<Ayah> = listOf(
    Ayah(1, 92, "وَالَّيْلِ اِذَا يَغْشٰىۙ", "Wal-laili iżā yagsyā.", "Demi malam apabila menutupi (cahaya siang),"),
    Ayah(2, 92, "وَالنَّهَارِ اِذَا تَجَلّٰىۙ", "Wan-nahāri iżā tajallā.", "demi siang apabila terang benderang,"),
    Ayah(3, 92, "وَمَا خَلَقَ الذَّكَرَ وَالْاُنْثٰىٓ ۙ", "Wa mā khalaqaż-żakara wal-unṡā.", "dan demi penciptaan laki-laki dan perempuan,"),
    Ayah(4, 92, "اِنَّ سَعْيَكُمْ لَشَتّٰىۗ", "Inna sa‘yakum lasyattā.", "sesungguhnya usahamu benar-benar beraneka ragam."),
    Ayah(5, 92, "فَاَمَّا مَنْ اَعْطٰى وَاتَّقٰىۙ", "Fa ammā man a‘ṭā wattaqā.", "Siapa yang memberikan (hartanya di jalan Allah) dan bertakwa"),
    Ayah(6, 92, "وَصَدَّقَ بِالْحُسْنٰىۙ", "Wa ṣaddaqa bil-ḥusnā.", "serta membenarkan adanya (balasan) yang terbaik (surga),"),
    Ayah(7, 92, "فَسَنُيَسِّرُهٗ لِلْيُسْرٰىۗ", "Fa sanuyassiruhū lil-yusrā.", "Kami akan melapangkan baginya jalan kemudahan (kebahagiaan)."),
    Ayah(8, 92, "وَاَمَّا مَنْۢ بَخِلَ وَاسْتَغْنٰىۙ", "Wa ammā man bakhila wastagnā.", "Adapun orang yang kikir dan merasa dirinya cukup (tidak perlu pertolongan Allah)"),
    Ayah(9, 92, "وَكَذَّبَ بِالْحُسْنٰىۙ", "Wa każżaba bil-ḥusnā.", "serta mendustakan (balasan) yang terbaik,"),
    Ayah(10, 92, "فَسَنُيَسِّرُهٗ لِلْعُسْرٰىۗ", "Fa sanuyassiruhū lil-‘usrā.", "Kami akan memudahkannya menuju jalan kesengsaraan."),
    Ayah(11, 92, "وَمَا يُغْنِيْ عَنْهُ مَالُهٗٓ اِذَا تَرَدّٰىٓۙ", "Wa mā yugnī ‘anhu māluhū iżā taraddā.", "Hartanya tidak bermanfaat baginya apabila dia telah binasa."),
    Ayah(12, 92, "اِنَّ عَلَيْنَا لَلْهُدٰىۖ", "Inna ‘alainā lal-hudā.", "Sesungguhnya Kamilah yang (berhak) memberi petunjuk."),
    Ayah(13, 92, "وَاِنَّ لَنَا لَلْاٰخِرَةَ وَالْاُوْلٰىۗ", "Wa inna lanā lal-ākhirata wal-ūlā.", "Sesungguhnya milik Kamilah akhirat dan dunia."),
    Ayah(14, 92, "فَاَنْذَرْتُكُمْ نَارًا تَلَظّٰىۚ", "Fa anżartukum nāran talaẓẓā.", "Aku memperingatkanmu dengan neraka yang menyala-nyala."),
    Ayah(15, 92, "لَا يَصْلٰىهَآ اِلَّا الْاَشْقَىۙ", "Lā yaṣlāhā illal-asyqā.", "Tidak masuk ke dalamnya kecuali orang yang paling celaka,"),
    Ayah(16, 92, "الَّذِيْ كَذَّبَ وَتَوَلّٰىۗ", "Allażī każżaba wa tawallā.", "yang mendustakan (kebenaran) dan berpaling (dari keimanan)."),
    Ayah(17, 92, "وَسَيُجَنَّبُهَا الْاَتْقَىۙ", "Wa sayujannabuhal-atqā.", "Akan dijauhkan darinya (neraka) orang yang paling bertakwa,"),
    Ayah(18, 92, "الَّذِيْ يُؤْتِيْ مَالَهٗ يَتَزَكّٰىۚ", "Allażī yu'tī mālahū yatazakkā.", "yang menginfakkan hartanya (di jalan Allah) untuk membersihkan (diri dari sifat kikir dan tamak)."),
    Ayah(19, 92, "وَمَا لِاَحَدٍ عِنْدَهٗ مِنْ نِّعْمَةٍ تُجْزٰىٓۙ", "Wa mā li'aḥadin ‘indahū min ni‘matin tujzā.", "Tidak ada suatu nikmat pun yang diberikan seseorang kepadanya yang harus dibalas,758)"),
    Ayah(20, 92, "اِلَّا ابْتِغَاۤءَ وَجْهِ رَبِّهِ الْاَعْلٰىۚ", "Illabtigā'a wajhi rabbihil-a‘lā.", "kecuali (dia memberikannya semata-mata) karena mencari keridaan Tuhannya Yang Mahatinggi."),
    Ayah(21, 92, "وَلَسَوْفَ يَرْضٰى ࣖ", "Wa lasaufa yarḍā.", "Sungguh, kelak dia akan mendapatkan kepuasan (menerima balasan amalnya)."),
)

internal fun quranFullAyahs93(): List<Ayah> = listOf(
    Ayah(1, 93, "وَالضُّحٰىۙ", "Waḍ-ḍuḥā.", "Demi waktu duha"),
    Ayah(2, 93, "وَالَّيْلِ اِذَا سَجٰىۙ", "Wal-laili iżā sajā.", "dan demi waktu malam apabila telah sunyi,"),
    Ayah(3, 93, "مَا وَدَّعَكَ رَبُّكَ وَمَا قَلٰىۗ", "Mā wadda‘aka rabbuka wa mā qalā.", "Tuhanmu (Nabi Muhammad) tidak meninggalkan dan tidak (pula) membencimu."),
    Ayah(4, 93, "وَلَلْاٰخِرَةُ خَيْرٌ لَّكَ مِنَ الْاُوْلٰىۗ", "Wa lal-ākhiratu khairul laka minal-ūlā.", "Sungguh, akhirat itu lebih baik bagimu daripada yang permulaan (dunia)."),
    Ayah(5, 93, "وَلَسَوْفَ يُعْطِيْكَ رَبُّكَ فَتَرْضٰىۗ", "Wa lasaufa yu‘ṭīka rabbuka fa tarḍā.", "Sungguh, kelak (di akhirat nanti) Tuhanmu pasti memberikan karunia-Nya kepadamu sehingga engkau rida."),
    Ayah(6, 93, "اَلَمْ يَجِدْكَ يَتِيْمًا فَاٰوٰىۖ", "Alam yajidka yatīman fa āwā.", "Bukankah Dia mendapatimu sebagai seorang yatim, lalu Dia melindungi(-mu);"),
    Ayah(7, 93, "وَوَجَدَكَ ضَاۤلًّا فَهَدٰىۖ", "Wa wajadaka ḍāllan fa hadā.", "mendapatimu sebagai seorang yang tidak tahu (tentang syariat), lalu Dia memberimu petunjuk (wahyu);"),
    Ayah(8, 93, "وَوَجَدَكَ عَاۤىِٕلًا فَاَغْنٰىۗ", "Wa wajadaka ‘ā'ilan fa agnā.", "dan mendapatimu sebagai seorang yang fakir, lalu Dia memberimu kecukupan?"),
    Ayah(9, 93, "فَاَمَّا الْيَتِيْمَ فَلَا تَقْهَرْۗ", "Fa ammal-yatīma falā taqhar.", "Terhadap anak yatim, janganlah engkau berlaku sewenang-wenang."),
    Ayah(10, 93, "وَاَمَّا السَّاۤىِٕلَ فَلَا تَنْهَرْ", "Wa ammas-sā'ila falā tanhar.", "Terhadap orang yang meminta-minta, janganlah engkau menghardik."),
    Ayah(11, 93, "وَاَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ ࣖ", "Wa ammā bini‘mati rabbika fa ḥaddiṡ.", "Terhadap nikmat Tuhanmu, nyatakanlah (dengan bersyukur)."),
)

internal fun quranFullAyahs94(): List<Ayah> = listOf(
    Ayah(1, 94, "اَلَمْ نَشْرَحْ لَكَ صَدْرَكَۙ", "Alam nasyraḥ laka ṣadrak(a).", "Bukankah Kami telah melapangkan dadamu (Nabi Muhammad),"),
    Ayah(2, 94, "وَوَضَعْنَا عَنْكَ وِزْرَكَۙ", "Wa waḍa‘nā ‘anka wizrak(a).", "meringankan beban (tugas-tugas kenabian) darimu"),
    Ayah(3, 94, "الَّذِيْٓ اَنْقَضَ ظَهْرَكَۙ", "Allażī anqaḍa ẓahrak(a).", "yang memberatkan punggungmu,"),
    Ayah(4, 94, "وَرَفَعْنَا لَكَ ذِكْرَكَۗ", "Wa rafa‘nā laka żikrak(a).", "dan meninggikan (derajat)-mu (dengan selalu) menyebut-nyebut (nama)-mu?"),
    Ayah(5, 94, "فَاِنَّ مَعَ الْعُسْرِ يُسْرًاۙ", "Fa'inna ma‘al-‘usri yusrā(n).", "Maka, sesungguhnya beserta kesulitan ada kemudahan."),
    Ayah(6, 94, "اِنَّ مَعَ الْعُسْرِ يُسْرًاۗ", "Inna ma‘al-‘usri yusrā(n).", "Sesungguhnya beserta kesulitan ada kemudahan."),
    Ayah(7, 94, "فَاِذَا فَرَغْتَ فَانْصَبْۙ", "Fa iżā faragta fanṣab.", "Apabila engkau telah selesai (dengan suatu kebajikan), teruslah bekerja keras (untuk kebajikan yang lain)"),
    Ayah(8, 94, "وَاِلٰى رَبِّكَ فَارْغَبْ ࣖ", "Wa ilā rabbika fargab.", "dan hanya kepada Tuhanmu berharaplah!"),
)

internal fun quranFullAyahs95(): List<Ayah> = listOf(
    Ayah(1, 95, "وَالتِّيْنِ وَالزَّيْتُوْنِۙ", "Wat-tīni waz-zaitūn(i).", "Demi (buah) tin dan (buah) zaitun,"),
    Ayah(2, 95, "وَطُوْرِ سِيْنِيْنَۙ", "Wa ṭūri sīnīn(a).", "demi gunung Sinai,"),
    Ayah(3, 95, "وَهٰذَا الْبَلَدِ الْاَمِيْنِۙ", "Wa hāżal-baladil-amīn(i).", "dan demi negeri (Makkah) yang aman ini,"),
    Ayah(4, 95, "لَقَدْ خَلَقْنَا الْاِنْسَانَ فِيْٓ اَحْسَنِ تَقْوِيْمٍۖ", "Laqad khalaqnal-insāna fī aḥsani taqwīm(in).", "sungguh, Kami benar-benar telah menciptakan manusia dalam bentuk yang sebaik-baiknya."),
    Ayah(5, 95, "ثُمَّ رَدَدْنٰهُ اَسْفَلَ سٰفِلِيْنَۙ", "Ṡumma radadnāhu asfala sāfilīn(a).", "Kemudian, kami kembalikan dia ke tempat yang serendah-rendahnya,"),
    Ayah(6, 95, "اِلَّا الَّذِيْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِ فَلَهُمْ اَجْرٌ غَيْرُ مَمْنُوْنٍۗ", "Illal-lażīna āmanū wa ‘amiluṣ-ṣāliḥāti falahum ajrun gairu mamnūn(in).", "kecuali orang-orang yang beriman dan mengerjakan kebajikan. Maka, mereka akan mendapat pahala yang tidak putus-putusnya."),
    Ayah(7, 95, "فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّيْنِۗ", "Famā yukażżibuka ba‘du bid-dīn(i).", "Maka, apa alasanmu (wahai orang kafir) mendustakan hari Pembalasan setelah (adanya bukti-bukti) itu?"),
    Ayah(8, 95, "اَلَيْسَ اللّٰهُ بِاَحْكَمِ الْحٰكِمِيْنَ ࣖ", "Alaisallāhu bi'aḥkamil-ḥākimīn(a).", "Bukankah Allah hakim yang paling adil?"),
)

